extends Node
## Global state: save data, settings, fonts, audio, input map, shared materials.

const SAVE_PATH := "user://cloudbreaker.cfg"
const VERSION := "1.0"

# ---------------------------------------------------------------- upgrades
const UPGRADES := {
	"power": {"name": "BLASTER POWER", "desc": "Bolts hit harder", "costs": [40, 90, 160], "vals": [1.0, 1.5, 2.0, 2.7]},
	"rate": {"name": "FIRE RATE", "desc": "Shoot faster", "costs": [40, 90, 160], "vals": [0.24, 0.19, 0.15, 0.11]},
	"glide": {"name": "GLIDER SPEED", "desc": "Faster wings", "costs": [50, 120], "vals": [17.0, 20.5, 24.0]},
	"hearts": {"name": "ENERGY CELLS", "desc": "More health", "costs": [60, 120, 200], "vals": [5, 6, 7, 8]},
	"dash": {"name": "AIR DASH", "desc": "Dash twice in the air", "costs": [150], "vals": [1, 2]},
	"hook": {"name": "HOOK RANGE", "desc": "Grapple from farther", "costs": [50, 120], "vals": [30.0, 38.0, 46.0]},
}
const UPGRADE_ORDER := ["power", "rate", "hearts", "glide", "hook", "dash"]

const PAINTS := {
	"sky": {"name": "SKY KNIGHT", "cost": 0, "main": Color(0.92, 0.94, 0.98), "trim": Color(0.16, 0.42, 0.95), "glow": Color(0.3, 0.85, 1.0)},
	"ember": {"name": "EMBER", "cost": 40, "main": Color(0.18, 0.17, 0.19), "trim": Color(1.0, 0.42, 0.08), "glow": Color(1.0, 0.55, 0.15)},
	"jade": {"name": "JADE", "cost": 40, "main": Color(0.9, 0.95, 0.9), "trim": Color(0.05, 0.6, 0.38), "glow": Color(0.25, 1.0, 0.6)},
	"frost": {"name": "FROST", "cost": 60, "main": Color(0.75, 0.88, 1.0), "trim": Color(0.55, 0.75, 1.0), "glow": Color(0.75, 0.95, 1.0)},
	"shadow": {"name": "SHADOW", "cost": 90, "main": Color(0.1, 0.1, 0.13), "trim": Color(0.45, 0.2, 0.95), "glow": Color(0.75, 0.35, 1.0)},
	"gold": {"name": "SOLAR GOLD", "cost": 150, "main": Color(0.95, 0.78, 0.32), "trim": Color(0.55, 0.32, 0.08), "glow": Color(1.0, 0.9, 0.5)},
	"prism": {"name": "PRISM (beat the Titan)", "cost": -1, "main": Color(0.95, 0.95, 1.0), "trim": Color(0.9, 0.3, 0.8), "glow": Color(1, 1, 1)},
}
const PAINT_ORDER := ["sky", "ember", "jade", "frost", "shadow", "gold", "prism"]

const ISLAND_NAMES := ["EMERALD STEPS", "HOOK CANYON", "DRONE FOUNDRY", "WIND RINGS", "CRYSTAL SPIRE"]

var data := {}
var settings := {"sound": true, "music": true, "quality": "high", "sens": 1.0, "invert": false, "assist": true}

# command line
var arg_screen := ""
var arg_fast := false
var arg_selftest := false
var arg_check := false
var arg_shot := ""
var arg_frames := 120
var is_touch := false

# fonts
var f_title: Font
var f_bold: Font
var f_body: Font
var f_heavy: Font
var theme: Theme

# audio
var streams := {}
var pool: Array[AudioStreamPlayer] = []
var pool3d: Array[AudioStreamPlayer3D] = []
var music_a: AudioStreamPlayer
var music_name := ""
var loop_players := {}
var last_play := {}

# shared materials (filled by world)
var mats := {}


func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	for a in OS.get_cmdline_user_args():
		if a.begins_with("--screen="):
			arg_screen = a.substr(9)
		elif a == "--fast":
			arg_fast = true
		elif a == "--selftest":
			arg_selftest = true
		elif a == "--check":
			arg_check = true
		elif a.begins_with("--shot="):
			arg_shot = a.substr(7)
		elif a.begins_with("--frames="):
			arg_frames = int(a.substr(9))
	is_touch = DisplayServer.is_touchscreen_available()
	if arg_screen == "touch":
		is_touch = true
	_setup_input()
	_setup_fonts()
	_setup_audio()
	load_game()
	if arg_fast:
		settings.quality = "fast"


# ---------------------------------------------------------------- save
func default_data() -> Dictionary:
	return {
		"shards": 0,
		"cores": [false, false, false, false, false],
		"shard_bits": PackedByteArray(),
		"prism_bits": PackedByteArray(),
		"up": {"power": 0, "rate": 0, "glide": 0, "hearts": 0, "dash": 0, "hook": 0},
		"paint": "sky",
		"paints": ["sky"],
		"boss": false,
		"boss_tries": 0,
		"ring_best": 0.0,
		"steps_best": 0.0,
		"checkpoint": -1,
		"time": 0.0,
		"drones": 0,
		"seen_intro": false,
		"visited": [false, false, false, false, false],
		"tips": {},
	}


func load_game() -> void:
	data = default_data()
	var cf := ConfigFile.new()
	if cf.load(SAVE_PATH) == OK:
		var d = cf.get_value("game", "data", {})
		if d is Dictionary:
			for k in d.keys():
				data[k] = d[k]
		var s = cf.get_value("game", "settings", {})
		if s is Dictionary:
			for k in s.keys():
				settings[k] = s[k]
	# repair
	var dd := default_data()
	for k in dd.keys():
		if not data.has(k):
			data[k] = dd[k]
	for k in dd.up.keys():
		if not data.up.has(k):
			data.up[k] = 0


func save_game() -> void:
	if arg_selftest or arg_screen != "" or arg_shot != "":
		return
	var cf := ConfigFile.new()
	cf.set_value("game", "data", data)
	cf.set_value("game", "settings", settings)
	cf.save(SAVE_PATH)


func reset_game() -> void:
	data = default_data()
	save_game()


func up_val(key: String):
	var lv: int = int(data.up.get(key, 0))
	var vals: Array = UPGRADES[key].vals
	return vals[clampi(lv, 0, vals.size() - 1)]


func cores_count() -> int:
	var n := 0
	for c in data.cores:
		if c:
			n += 1
	return n


func bit_get(key: String, i: int) -> bool:
	var b: PackedByteArray = data[key]
	if i / 8 >= b.size():
		return false
	return (b[i / 8] >> (i % 8)) & 1 == 1


func bit_set(key: String, i: int) -> void:
	var b: PackedByteArray = data[key]
	while b.size() <= i / 8:
		b.append(0)
	b[i / 8] = b[i / 8] | (1 << (i % 8))
	data[key] = b


# ---------------------------------------------------------------- input
func _key(code: Key) -> InputEventKey:
	var e := InputEventKey.new()
	e.physical_keycode = code
	return e


func _joy_btn(b: JoyButton) -> InputEventJoypadButton:
	var e := InputEventJoypadButton.new()
	e.button_index = b
	return e


func _joy_axis(a: JoyAxis, v: float) -> InputEventJoypadMotion:
	var e := InputEventJoypadMotion.new()
	e.axis = a
	e.axis_value = v
	return e


func _mouse(b: MouseButton) -> InputEventMouseButton:
	var e := InputEventMouseButton.new()
	e.button_index = b
	return e


func _add(action: String, events: Array) -> void:
	if not InputMap.has_action(action):
		InputMap.add_action(action, 0.25)
	for e in events:
		InputMap.action_add_event(action, e)


func _setup_input() -> void:
	_add("move_f", [_key(KEY_W), _joy_axis(JOY_AXIS_LEFT_Y, -1.0)])
	_add("move_b", [_key(KEY_S), _joy_axis(JOY_AXIS_LEFT_Y, 1.0)])
	_add("move_l", [_key(KEY_A), _joy_axis(JOY_AXIS_LEFT_X, -1.0)])
	_add("move_r", [_key(KEY_D), _joy_axis(JOY_AXIS_LEFT_X, 1.0)])
	_add("cam_l", [_key(KEY_LEFT), _joy_axis(JOY_AXIS_RIGHT_X, -1.0)])
	_add("cam_r", [_key(KEY_RIGHT), _joy_axis(JOY_AXIS_RIGHT_X, 1.0)])
	_add("cam_u", [_key(KEY_UP), _joy_axis(JOY_AXIS_RIGHT_Y, -1.0)])
	_add("cam_d", [_key(KEY_DOWN), _joy_axis(JOY_AXIS_RIGHT_Y, 1.0)])
	_add("jump", [_key(KEY_SPACE), _joy_btn(JOY_BUTTON_A)])
	_add("dash", [_key(KEY_SHIFT), _key(KEY_K), _joy_btn(JOY_BUTTON_B), _joy_btn(JOY_BUTTON_LEFT_SHOULDER)])
	_add("hook", [_key(KEY_E), _key(KEY_L), _joy_btn(JOY_BUTTON_X)])
	_add("fire", [_key(KEY_F), _key(KEY_J), _joy_axis(JOY_AXIS_TRIGGER_RIGHT, 1.0), _joy_btn(JOY_BUTTON_RIGHT_SHOULDER)])
	_add("interact", [_key(KEY_R), _key(KEY_ENTER), _joy_btn(JOY_BUTTON_Y)])
	_add("pause", [_key(KEY_ESCAPE), _key(KEY_P), _joy_btn(JOY_BUTTON_START)])


# ---------------------------------------------------------------- fonts
func _font(path: String) -> Font:
	var f = load(path)
	if f == null:
		return ThemeDB.fallback_font
	var sym = load("res://assets/fonts/symbols.ttf")
	if sym != null and f is FontFile:
		var fv := FontVariation.new()
		fv.base_font = f
		fv.fallbacks = [sym]
		return fv
	return f


func _setup_fonts() -> void:
	f_title = _font("res://assets/fonts/russo.ttf")
	f_bold = _font("res://assets/fonts/exo700.ttf")
	f_body = _font("res://assets/fonts/exo400.ttf")
	f_heavy = _font("res://assets/fonts/exo800.ttf")
	theme = Theme.new()
	theme.default_font = f_bold
	theme.default_font_size = 20


# ---------------------------------------------------------------- audio
func _setup_audio() -> void:
	var dir := "res://assets/sfx/"
	for n in ["jump", "jump2", "land", "dash", "wind", "wings", "hook", "latch", "zip", "blaster", "hit", "boom", "bigboom", "shard", "core", "hurt", "launch", "click", "select", "buy", "deny", "hum", "elaser", "checkpoint", "ring", "roar", "shock", "missile", "thunder", "warn", "shield", "victory", "respawn", "anvil"]:
		var s = load(dir + n + ".wav")
		if s != null:
			streams[n] = s
	for n in ["music_title", "music_explore", "music_boss", "music_victory"]:
		var m = load(dir + n + ".ogg")
		if m != null:
			if m is AudioStreamOggVorbis:
				m.loop = true
			streams[n] = m
	if streams.has("wind"):
		var w = streams.wind
		if w is AudioStreamWAV:
			w.loop_mode = AudioStreamWAV.LOOP_FORWARD
			w.loop_end = int(w.get_length() * w.mix_rate)
	if streams.has("hum"):
		var h = streams.hum
		if h is AudioStreamWAV:
			h.loop_mode = AudioStreamWAV.LOOP_FORWARD
			h.loop_end = int(h.get_length() * h.mix_rate)
	for i in 14:
		var p := AudioStreamPlayer.new()
		add_child(p)
		pool.append(p)
	music_a = AudioStreamPlayer.new()
	music_a.volume_db = -8.0
	add_child(music_a)


func play(name: String, vol_db: float = 0.0, pitch: float = 1.0, min_gap: float = 0.03) -> void:
	if not settings.sound or not streams.has(name):
		return
	var now := Time.get_ticks_msec() / 1000.0
	if now - float(last_play.get(name, -10.0)) < min_gap:
		return
	last_play[name] = now
	var best: AudioStreamPlayer = null
	for p in pool:
		if not p.playing:
			best = p
			break
	if best == null:
		best = pool[randi() % pool.size()]
	best.stream = streams[name]
	best.volume_db = vol_db
	best.pitch_scale = pitch
	best.play()


func play_at(name: String, pos: Vector3, listener: Vector3, vol_db: float = 0.0, pitch: float = 1.0, max_dist: float = 90.0) -> void:
	var d := pos.distance_to(listener)
	if d > max_dist:
		return
	var att := lerpf(0.0, -22.0, clampf(d / max_dist, 0.0, 1.0))
	play(name, vol_db + att, pitch, 0.02)


func loop(name: String, on: bool, vol_db: float = 0.0, pitch: float = 1.0) -> void:
	var p: AudioStreamPlayer = loop_players.get(name)
	if p == null:
		if not on or not streams.has(name):
			return
		p = AudioStreamPlayer.new()
		p.stream = streams[name]
		add_child(p)
		loop_players[name] = p
	if on and settings.sound:
		p.volume_db = vol_db
		p.pitch_scale = pitch
		if not p.playing:
			p.play()
	else:
		if p.playing:
			p.stop()


func stop_loops() -> void:
	for k in loop_players.keys():
		loop_players[k].stop()


func music(name: String) -> void:
	if name == music_name and music_a.playing:
		return
	music_name = name
	if not settings.music or name == "" or not streams.has(name):
		music_a.stop()
		return
	music_a.stream = streams[name]
	music_a.volume_db = -9.0 if name != "music_boss" else -7.0
	music_a.play()


func refresh_music() -> void:
	var n := music_name
	music_name = ""
	music(n)


# ---------------------------------------------------------------- helpers
func label_settings(font: Font, size: int, color: Color, outline: int = 0, outline_color: Color = Color(0, 0, 0, 0.6), shadow: bool = false) -> LabelSettings:
	var ls := LabelSettings.new()
	ls.font = font
	ls.font_size = size
	ls.font_color = color
	ls.outline_size = outline
	ls.outline_color = outline_color
	if shadow:
		ls.shadow_size = 6
		ls.shadow_color = Color(0, 0, 0, 0.45)
		ls.shadow_offset = Vector2(0, 3)
	return ls


func tex(name: String) -> Texture2D:
	return load("res://assets/tex/" + name + ".png")

