class_name Geo
extends RefCounted
## Procedural geometry helpers: floating islands, rocks, trees, crystals, grass, pillars.


class IslandData:
	extends RefCounted
	var R := 20.0
	var depth := 30.0
	var amp := 0.8
	var noise := FastNoiseLite.new()
	var rim_noise := FastNoiseLite.new()
	var plateau := 0.0
	var path_fn: Callable
	var origin := Vector3.ZERO
	var rim_var := 0.12

	func rim(theta: float) -> float:
		var n := rim_noise.get_noise_2d(cos(theta) * 40.0, sin(theta) * 40.0)
		return R * (1.0 - rim_var + rim_var * 2.0 * (n * 0.5 + 0.5))

	func top_h(x: float, z: float) -> float:
		var r := sqrt(x * x + z * z)
		var th := atan2(z, x)
		var rr := rim(th)
		var t := clampf(r / rr, 0.0, 1.0)
		var h := noise.get_noise_2d(x, z) * amp
		h *= 1.0 - plateau * (1.0 - smoothstep(0.55, 0.95, t))
		# gentle dome, slight lip drop at the edge
		h += (1.0 - t * t) * amp * 0.6 - smoothstep(0.86, 1.0, t) * 0.8
		return h

	func inside(x: float, z: float, margin: float = 0.9) -> bool:
		var r := sqrt(x * x + z * z)
		return r < rim(atan2(z, x)) * margin

	func rand_point(rng: RandomNumberGenerator, margin: float = 0.88, min_r: float = 0.0) -> Vector3:
		for i in 30:
			var a := rng.randf() * TAU
			var r := sqrt(rng.randf()) * R
			var x := cos(a) * r
			var z := sin(a) * r
			if r >= min_r and inside(x, z, margin):
				return Vector3(x, top_h(x, z), z)
		return Vector3(0, top_h(0, 0), 0)


static func make_island(R: float, depth: float, seed: int, amp: float = 0.8, rings: int = 0, segs: int = 0, plateau: float = 0.0, rim_var: float = 0.12) -> Dictionary:
	var d := IslandData.new()
	d.R = R
	d.depth = depth
	d.amp = amp
	d.plateau = plateau
	d.rim_var = rim_var
	d.noise.seed = seed
	d.noise.frequency = 0.035
	d.noise.fractal_octaves = 3
	d.rim_noise.seed = seed + 17
	d.rim_noise.frequency = 0.05
	d.rim_noise.fractal_octaves = 2
	if rings <= 0:
		rings = clampi(int(R / 2.2), 4, 22)
	if segs <= 0:
		segs = clampi(int(R * 2.2), 14, 96)
	var n3 := FastNoiseLite.new()
	n3.seed = seed + 5
	n3.frequency = 0.06
	n3.fractal_octaves = 3

	var st := SurfaceTool.new()
	st.begin(Mesh.PRIMITIVE_TRIANGLES)
	var verts := PackedVector3Array()
	var cols := PackedColorArray()
	# ---- top surface (polar grid) ----
	var top_idx := []
	verts.append(Vector3(0, d.top_h(0, 0), 0))
	cols.append(Color(1, 0, 0))
	for j in range(1, rings + 1):
		var row := []
		for i in segs:
			var th := float(i) / segs * TAU
			var rr := d.rim(th) * float(j) / rings
			var x := cos(th) * rr
			var z := sin(th) * rr
			row.append(verts.size())
			var pm := 0.0
			if d.path_fn.is_valid():
				pm = d.path_fn.call(x, z)
			verts.append(Vector3(x, d.top_h(x, z), z))
			cols.append(Color(1, pm, 0))
		top_idx.append(row)
	var tris := PackedInt32Array()
	# center fan
	for i in segs:
		var a: int = top_idx[0][i]
		var b: int = top_idx[0][(i + 1) % segs]
		tris.append_array([0, a, b])
	for j in range(rings - 1):
		for i in segs:
			var a: int = top_idx[j][i]
			var b: int = top_idx[j][(i + 1) % segs]
			var c: int = top_idx[j + 1][i]
			var e: int = top_idx[j + 1][(i + 1) % segs]
			tris.append_array([a, e, b, a, c, e])
	# ---- cliff skirt + underside to a tip ----
	var K := clampi(int(depth / 3.0), 6, 26)
	var side_rows := []
	for k in K + 1:
		var t := float(k) / K
		var row := []
		for i in segs:
			var th := float(i) / segs * TAU
			var rr := d.rim(th)
			var x0 := cos(th) * rr
			var z0 := sin(th) * rr
			var y: float
			var rad: float
			if k == 0:
				y = d.top_h(x0, z0)
				rad = 1.0
			else:
				# shape: steep cliff near the top, then tapering to a point
				y = -t * depth
				var prof := pow(1.0 - t, 0.85)
				prof *= 1.0 + 0.06 * sin(t * 9.0 + th * 3.0)
				if k == 1:
					y = d.top_h(x0, z0) - 1.4
					prof = 1.03
				rad = prof
			var p := Vector3(cos(th) * rr * rad, y, sin(th) * rr * rad)
			var n := n3.get_noise_3d(p.x, p.y * 0.7, p.z)
			var push := n * (2.0 + R * 0.08) * (0.3 if k <= 1 else 1.0)
			p.x += cos(th) * push
			p.z += sin(th) * push
			if k == K:
				p = Vector3(0, -depth - 2.0, 0)
			row.append(verts.size())
			verts.append(p)
			cols.append(Color(0, 0, clampf(t * 0.75, 0.0, 0.7)))
		side_rows.append(row)
	for k in K:
		for i in segs:
			var a: int = side_rows[k][i]
			var b: int = side_rows[k][(i + 1) % segs]
			var c: int = side_rows[k + 1][i]
			var e: int = side_rows[k + 1][(i + 1) % segs]
			tris.append_array([a, e, b, a, c, e])
	for idx in tris:
		st.set_color(cols[idx])
		st.add_vertex(verts[idx])
	st.generate_normals()
	var mesh := st.commit()
	# collision faces (top + upper skirt is enough for gameplay, include all for safety)
	var faces := PackedVector3Array()
	for idx in tris:
		faces.append(verts[idx])
	var shape := ConcavePolygonShape3D.new()
	shape.set_faces(faces)
	shape.backface_collision = true
	return {"mesh": mesh, "shape": shape, "data": d}


static func displaced_sphere(radius: float, seed: int, amount: float, rad_segs: int = 16, rings: int = 10, squash: Vector3 = Vector3.ONE, freq: float = 0.9) -> ArrayMesh:
	var sm := SphereMesh.new()
	sm.radius = radius
	sm.height = radius * 2.0
	sm.radial_segments = rad_segs
	sm.rings = rings
	var arr := sm.get_mesh_arrays()
	var v: PackedVector3Array = arr[Mesh.ARRAY_VERTEX]
	var n := FastNoiseLite.new()
	n.seed = seed
	n.frequency = freq / radius
	n.fractal_octaves = 2
	# seam-safe: noise depends on position only
	for i in v.size():
		var p := v[i]
		var dir := p.normalized()
		var k := n.get_noise_3d(p.x, p.y, p.z)
		v[i] = (p + dir * k * amount * radius) * squash
	var st := SurfaceTool.new()
	st.begin(Mesh.PRIMITIVE_TRIANGLES)
	var idx: PackedInt32Array = arr[Mesh.ARRAY_INDEX]
	for i in idx:
		st.add_vertex(v[i])
	st.generate_normals()
	return st.commit()


static func grass_clump(blades: int = 7, h: float = 0.55, seed: int = 3) -> ArrayMesh:
	var rng := RandomNumberGenerator.new()
	rng.seed = seed
	var st := SurfaceTool.new()
	st.begin(Mesh.PRIMITIVE_TRIANGLES)
	for b in blades:
		var a := rng.randf() * TAU
		var r := rng.randf() * 0.25
		var base := Vector3(cos(a) * r, 0, sin(a) * r)
		var dir := Vector3(cos(a + PI / 2), 0, sin(a + PI / 2))
		var lean := Vector3(cos(a), 0, sin(a)) * rng.randf_range(0.05, 0.25)
		var bh := h * rng.randf_range(0.6, 1.25)
		var w := 0.045
		var p0 := base - dir * w
		var p1 := base + dir * w
		var p2 := base + lean * 0.5 + Vector3(0, bh * 0.55, 0) - dir * w * 0.7
		var p3 := base + lean * 0.5 + Vector3(0, bh * 0.55, 0) + dir * w * 0.7
		var p4 := base + lean + Vector3(0, bh, 0)
		var c0 := Color(0, 0, 0)
		var c1 := Color(0.55, 0, 0)
		var c2 := Color(1, 0, 0)
		for tri in [[p0, p1, p3, c0, c0, c1], [p0, p3, p2, c0, c1, c1], [p2, p3, p4, c1, c1, c2]]:
			st.set_normal(Vector3.UP)
			st.set_color(tri[3]); st.add_vertex(tri[0])
			st.set_color(tri[4]); st.add_vertex(tri[1])
			st.set_color(tri[5]); st.add_vertex(tri[2])
	return st.commit()


static func crystal(h: float = 3.0, r: float = 0.5, sides: int = 6, tip: float = 0.8) -> ArrayMesh:
	var st := SurfaceTool.new()
	st.begin(Mesh.PRIMITIVE_TRIANGLES)
	var top := Vector3(0, h + tip, 0)
	var bot := Vector3(0, -0.2, 0)
	for i in sides:
		var a0 := float(i) / sides * TAU
		var a1 := float(i + 1) / sides * TAU
		var b0 := Vector3(cos(a0) * r, 0, sin(a0) * r)
		var b1 := Vector3(cos(a1) * r, 0, sin(a1) * r)
		var t0 := b0 * 0.92 + Vector3(0, h, 0)
		var t1 := b1 * 0.92 + Vector3(0, h, 0)
		st.add_vertex(b0); st.add_vertex(t1); st.add_vertex(b1)
		st.add_vertex(b0); st.add_vertex(t0); st.add_vertex(t1)
		st.add_vertex(t0); st.add_vertex(top); st.add_vertex(t1)
		st.add_vertex(b0); st.add_vertex(b1); st.add_vertex(bot)
	st.generate_normals()
	return st.commit()


static func crystal_cluster(seed: int, count: int = 5, scale: float = 1.0) -> ArrayMesh:
	var rng := RandomNumberGenerator.new()
	rng.seed = seed
	var st := SurfaceTool.new()
	st.begin(Mesh.PRIMITIVE_TRIANGLES)
	for c in count:
		var h := rng.randf_range(1.2, 3.2) * scale * (1.4 if c == 0 else 1.0)
		var r := rng.randf_range(0.25, 0.5) * scale
		var m := crystal(h, r, 6, r * 1.6)
		var basis := Basis(Vector3(rng.randf_range(-1, 1), 0, rng.randf_range(-1, 1)).normalized() if c > 0 else Vector3.UP, rng.randf_range(0.2, 0.6) if c > 0 else 0.0)
		if c > 0 and basis.get_euler() == Vector3.ZERO:
			basis = Basis()
		var off := Vector3(rng.randf_range(-0.5, 0.5), 0, rng.randf_range(-0.5, 0.5)) * scale * (0.0 if c == 0 else 1.0)
		st.append_from(m, 0, Transform3D(basis, off))
	return st.commit()


static func pillar(h: float = 6.0, r: float = 0.6, broken: bool = false, seed: int = 0) -> ArrayMesh:
	# fluted column with a base and capital
	var st := SurfaceTool.new()
	st.begin(Mesh.PRIMITIVE_TRIANGLES)
	var base := BoxMesh.new()
	base.size = Vector3(r * 2.6, 0.4, r * 2.6)
	st.append_from(base, 0, Transform3D(Basis(), Vector3(0, 0.2, 0)))
	var base2 := BoxMesh.new()
	base2.size = Vector3(r * 2.2, 0.3, r * 2.2)
	st.append_from(base2, 0, Transform3D(Basis(), Vector3(0, 0.55, 0)))
	var shaft_h := h - 1.3
	if broken:
		var rng := RandomNumberGenerator.new()
		rng.seed = seed
		shaft_h *= rng.randf_range(0.35, 0.75)
	var cyl := CylinderMesh.new()
	cyl.top_radius = r * 0.88
	cyl.bottom_radius = r
	cyl.height = shaft_h
	cyl.radial_segments = 16
	cyl.rings = 1
	st.append_from(cyl, 0, Transform3D(Basis(), Vector3(0, 0.7 + shaft_h / 2.0, 0)))
	if not broken:
		var cap := BoxMesh.new()
		cap.size = Vector3(r * 2.4, 0.35, r * 2.4)
		st.append_from(cap, 0, Transform3D(Basis(), Vector3(0, 0.7 + shaft_h + 0.18, 0)))
		var cap2 := CylinderMesh.new()
		cap2.top_radius = r * 1.15
		cap2.bottom_radius = r * 0.9
		cap2.height = 0.3
		st.append_from(cap2, 0, Transform3D(Basis(), Vector3(0, 0.7 + shaft_h - 0.1, 0)))
	st.generate_normals()
	return st.commit()


static func tube(points: PackedVector3Array, radius: float, sides: int = 8) -> ArrayMesh:
	var st := SurfaceTool.new()
	st.begin(Mesh.PRIMITIVE_TRIANGLES)
	var rings := []
	for i in points.size():
		var p := points[i]
		var fwd: Vector3
		if i < points.size() - 1:
			fwd = (points[i + 1] - p).normalized()
		else:
			fwd = (p - points[i - 1]).normalized()
		var side := fwd.cross(Vector3.UP)
		if side.length() < 0.01:
			side = fwd.cross(Vector3.RIGHT)
		side = side.normalized()
		var upv := side.cross(fwd).normalized()
		var ring := []
		for s in sides:
			var a := float(s) / sides * TAU
			ring.append(p + (side * cos(a) + upv * sin(a)) * radius)
		rings.append(ring)
	for i in rings.size() - 1:
		for s in sides:
			var a: Vector3 = rings[i][s]
			var b: Vector3 = rings[i][(s + 1) % sides]
			var c: Vector3 = rings[i + 1][s]
			var e: Vector3 = rings[i + 1][(s + 1) % sides]
			st.add_vertex(a); st.add_vertex(b); st.add_vertex(e)
			st.add_vertex(a); st.add_vertex(e); st.add_vertex(c)
	st.generate_normals()
	return st.commit()


static func merge(parts: Array) -> ArrayMesh:
	# parts: [[Mesh, Transform3D], ...] -> single surface
	var st := SurfaceTool.new()
	st.begin(Mesh.PRIMITIVE_TRIANGLES)
	for p in parts:
		st.append_from(p[0], 0, p[1])
	st.generate_normals()
	return st.commit()


static func box(size: Vector3) -> BoxMesh:
	var b := BoxMesh.new()
	b.size = size
	return b


static func cyl(r_top: float, r_bot: float, h: float, segs: int = 16) -> CylinderMesh:
	var c := CylinderMesh.new()
	c.top_radius = r_top
	c.bottom_radius = r_bot
	c.height = h
	c.radial_segments = segs
	c.rings = 1
	return c


static func sphere(r: float, segs: int = 16, rings: int = 8) -> SphereMesh:
	var s := SphereMesh.new()
	s.radius = r
	s.height = r * 2
	s.radial_segments = segs
	s.rings = rings
	return s


static func torus(inner: float, outer: float, rings: int = 32, ring_segs: int = 10) -> TorusMesh:
	var t := TorusMesh.new()
	t.inner_radius = inner
	t.outer_radius = outer
	t.rings = rings
	t.ring_segments = ring_segs
	return t

