## Cloudbreaker main: game flow, camera, combat, missions, debug screens and the self-test bot.

const WorldScript = preload("res://scripts/world.gd")
const HudScript = preload("res://scripts/hud.gd")

var world
var hero: Hero
var cam: Camera3D
var hud
var fx_root: Node3D
var state := "boot"          # title, play, pause, forge, victory, menu
var t := 0.0
var cam_yaw := 0.0
var cam_pitch := -0.28
var cam_dist := 6.5
var cam_target := Vector3.ZERO
var cam_idle := 0.0
var cam_fov := 70.0
var shake_amt := 0.0
var drones: Array = []
var projs: Array = []
var shockwaves: Array = []
var strikes: Array = []
var debris: Array = []
var loot: Array = []
var titan: Titan = null
var inp := {"move": Vector2.ZERO, "jump_pressed": false, "jump_held": false, "dash_pressed": false, "hook_pressed": false, "fire_held": false, "interact_pressed": false}
var bot: Dictionary = {}     # self-test input override
var checkpoint: Dictionary = {}
var hook_cand: Dictionary = {}
var aim_target = null
var pad_cool := 0.0
var foundry := {"wave": 0, "state": "idle", "timer": 0.0}
var ring := {"active": false, "idx": 0, "time": 0.0, "elapsed": 0.0, "done": false}
var spire_spawned := false
var in_arena := false
var save_t := 0.0
var dirty := false
var shard_combo := 0
var shard_combo_t := 0.0
var down_t := 0.0
var fps_probe := {"t": 0.0, "frames": 0, "done": false}
var mouse_look := false
var title_t := 0.0
var victory_pending := -1.0
var gate_hint_t := 0.0
var arena_return_pad: Dictionary = {}
var prev_hero_pos := Vector3.ZERO
var context := ""
var forge_open_t := 0.0
var fall_limit := -70.0
var mission_msg := ""
var test_log: Array = []
var current_island := -1
var boss_time := 0.0
var _rmb_was := false
var _dbg_n := 0
var _shot_frames := 0


func _ready() -> void:
	if G.arg_check:
		print("CHECK OK")
		get_tree().quit()
		return
	world = WorldScript.new()
	add_child(world)
	world.build(G.settings.quality)
	fx_root = Node3D.new()
	add_child(fx_root)
	hero = Hero.new()
	hero.main = self
	add_child(hero)
	cam = Camera3D.new()
	cam.fov = 70.0
	cam.near = 0.1
	cam.far = 3200.0
	add_child(cam)
	cam.current = true
	hud = HudScript.new()
	hud.main = self
	add_child(hud)
	# restore progress
	for i in 5:
		if G.data.cores[i]:
			world.set_core_taken(i)
	if not G.data.cores[2]:
		world.set_core_visible(2, false)
	if not G.data.cores[3]:
		world.set_core_visible(3, false)
	world.update_gate(G.data.cores, G.cores_count() >= 5)
	if G.data.boss:
		world.set_clear_sky(1.0)
	for c in world.checkpoints:
		if c.get("hub", false):
			checkpoint = c
	world.set_checkpoint_on(checkpoint, true)
	hero.respawn_at(checkpoint.pos + Vector3(0, 1.0, 2.0), 0.0)
	hero.hearts = hero.max_hearts
	cam_target = hero.global_position
	if G.arg_selftest:
		run_selftest()
	elif G.arg_screen != "" and G.arg_screen != "title" and G.arg_screen != "touch":
		debug_screen(G.arg_screen)
	elif G.arg_screen == "touch":
		start_play()
	else:
		to_title()


# ------------------------------------------------------------------ states
func to_title() -> void:
	state = "title"
	title_t = 0.0
	hero.respawn_at(world.HUB + Vector3(0, 1.5, 0), PI)
	hero.mode = "ground"
	hud.show_title()
	G.music("music_title")
	_release_mouse()


func start_play() -> void:
	state = "play"
	hud.hide_menus()
	hud.show_hud(true)
	if not in_arena:
		G.music("music_explore")
	cam_yaw = hero.facing
	if not G.data.seen_intro:
		G.data.seen_intro = true
		hud.banner("WELCOME, SKY KNIGHT", "The Storm Titan has trapped the sky! Find the 5 Storm Cores.", Color(0.6, 0.9, 1.0))
		get_tree().create_timer(4.5).timeout.connect(func(): tip("move", "Move with the left stick (or WASD). JUMP twice for a double jump!"))
	fps_probe = {"t": 0.0, "frames": 0, "done": false}


func pause_game() -> void:
	if state != "play":
		return
	state = "pause"
	hud.show_pause()
	G.loop("wind", false)
	_release_mouse()


func resume() -> void:
	state = "play"
	hud.hide_menus()
	hud.show_hud(true)


func open_forge() -> void:
	state = "forge"
	G.play("anvil", -2.0)
	hud.show_forge()
	G.loop("wind", false)
	_release_mouse()


func close_forge() -> void:
	resume()
	hero.refresh_stats()
	G.save_game()


func _release_mouse() -> void:
	if Input.mouse_mode == Input.MOUSE_MODE_CAPTURED:
		Input.mouse_mode = Input.MOUSE_MODE_VISIBLE
	mouse_look = false


# ------------------------------------------------------------------ input
func _unhandled_input(event: InputEvent) -> void:
	if event.is_action_pressed("pause"):
		if state == "play":
			pause_game()
		elif state == "pause":
			resume()
		elif state == "forge":
			close_forge()
		get_viewport().set_input_as_handled()
		return
	if state != "play":
		return
	if event is InputEventMouseButton and event.pressed and not G.is_touch:
		if Input.mouse_mode != Input.MOUSE_MODE_CAPTURED:
			Input.mouse_mode = Input.MOUSE_MODE_CAPTURED
			mouse_look = true
	if event is InputEventMouseMotion and Input.mouse_mode == Input.MOUSE_MODE_CAPTURED:
		var s: float = 0.0032 * float(G.settings.sens)
		cam_yaw -= event.relative.x * s
		cam_pitch -= event.relative.y * s * (-1.0 if G.settings.invert else 1.0)
		cam_pitch = clampf(cam_pitch, -1.25, 0.75)
		cam_idle = 0.0


func _gather_input() -> void:
	if not bot.is_empty():
		inp.move = bot.get("move", Vector2.ZERO)
		inp.jump_pressed = bot.get("jump_pressed", false)
		inp.jump_held = bot.get("jump_held", false)
		inp.dash_pressed = bot.get("dash_pressed", false)
		inp.hook_pressed = bot.get("hook_pressed", false)
		inp.fire_held = bot.get("fire_held", false)
		inp.interact_pressed = bot.get("interact_pressed", false)
		bot.jump_pressed = false
		bot.dash_pressed = false
		bot.hook_pressed = false
		bot.interact_pressed = false
		return
	var mv := Vector2(Input.get_axis("move_l", "move_r"), Input.get_axis("move_b", "move_f"))
	mv += hud.touch_move
	inp.move = mv.limit_length(1.0)
	inp.jump_pressed = Input.is_action_just_pressed("jump") or hud.take("jump")
	inp.jump_held = Input.is_action_pressed("jump") or hud.held("jump")
	inp.dash_pressed = Input.is_action_just_pressed("dash") or hud.take("dash")
	inp.hook_pressed = Input.is_action_just_pressed("hook") or hud.take("hook")
	inp.fire_held = Input.is_action_pressed("fire") or hud.held("fire")
	inp.interact_pressed = Input.is_action_just_pressed("interact") or hud.take("interact")
	# mouse buttons only count while the mouse is captured (desktop play)
	if Input.mouse_mode == Input.MOUSE_MODE_CAPTURED:
		if Input.is_mouse_button_pressed(MOUSE_BUTTON_LEFT):
			inp.fire_held = true
		var rm := Input.is_mouse_button_pressed(MOUSE_BUTTON_RIGHT)
		if rm and not _rmb_was:
			inp.hook_pressed = true
		_rmb_was = rm


# ------------------------------------------------------------------ main loops
func _physics_process(dt: float) -> void:
	if world == null:
		return
	t += dt
	world.physics_update(t)
	if state == "title":
		hero.velocity = Vector3.ZERO
		return
	if state != "play":
		return
	G.data.time = float(G.data.time) + dt
	_gather_input()
	prev_hero_pos = hero.global_position
	hero.in_updraft = _in_updraft(hero.global_position)
	hero.control(dt, inp, cam_yaw)
	# hook
	hook_cand = _find_hook() if hero.can_hook() else {}
	if inp.hook_pressed:
		if not hook_cand.is_empty():
			hero.start_hook(hook_cand)
			tip_done("hook")
		elif hero.mode != "zip":
			G.play("deny", -10.0)
	# fire
	aim_target = _pick_target()
	if inp.fire_held and hero.can_fire():
		_fire_bolt()
	_update_projs(dt)
	_update_drones(dt)
	_update_titan(dt)
	_update_waves(dt)
	_update_strikes(dt)
	_update_loot(dt)
	_collect_shards()
	_check_pads(dt)
	_check_checkpoints()
	_check_cores()
	_update_foundry(dt)
	_update_rings(dt)
	_update_spire()
	_update_context()
	_check_fall()
	if hero.mode == "down":
		down_t -= dt
		if down_t <= 0.0:
			_respawn(false)
	if victory_pending > 0.0:
		victory_pending -= dt
		if victory_pending <= 0.0:
			_show_victory()
	if in_arena and titan != null and not titan.dead:
		boss_time += dt
	save_t += dt
	if save_t > 8.0:
		save_t = 0.0
		if dirty:
			dirty = false
			G.save_game()
	# auto quality
	if not fps_probe.done:
		fps_probe.t += dt
		if fps_probe.t > 2.0:
			fps_probe.frames += 1
		if fps_probe.t > 8.0:
			fps_probe.done = true
			var fps := Engine.get_frames_per_second()
			if fps < 33 and G.settings.quality == "high" and G.arg_screen == "":
				set_quality("fast")
				hud.toast("Graphics set to FAST for smoother flying")


func _process(dt: float) -> void:
	if world == null:
		return
	if G.arg_shot != "":
		_shot_frames += 1
		if _shot_frames == G.arg_frames:
			var img := get_viewport().get_texture().get_image()
			img.save_png(G.arg_shot)
			print("shot saved ", G.arg_shot, " fps ", Engine.get_frames_per_second(), " draws ", RenderingServer.get_rendering_info(RenderingServer.RENDERING_INFO_TOTAL_DRAW_CALLS_IN_FRAME), " prims ", RenderingServer.get_rendering_info(RenderingServer.RENDERING_INFO_TOTAL_PRIMITIVES_IN_FRAME), " objs ", RenderingServer.get_rendering_info(RenderingServer.RENDERING_INFO_TOTAL_OBJECTS_IN_FRAME))
			get_tree().quit()
	if state == "title":
		title_t += dt
		var a := title_t * 0.06 + 0.6
		var p: Vector3 = world.HUB + Vector3(sin(a) * 46.0, 16.0 + sin(title_t * 0.2) * 3.0, cos(a) * 46.0)
		cam.global_position = p
		cam.look_at(world.HUB + Vector3(0, 6, 0), Vector3.UP)
		cam.fov = 62.0
		hero.facing = atan2(-(p.x - hero.global_position.x), -(p.z - hero.global_position.z))
	elif state != "look":
		_update_camera(dt)
	hero.animate(dt, t)
	world.update(dt, cam.global_position, hero.global_position, t)
	_update_arena_mood(dt)
	hud.update_view(dt)


# ------------------------------------------------------------------ camera
func _update_camera(dt: float) -> void:
	# camera input: keys/pad + touch drag
	var ci := Vector2(Input.get_axis("cam_l", "cam_r"), Input.get_axis("cam_d", "cam_u"))
	var sens: float = float(G.settings.sens)
	if ci.length() > 0.1:
		cam_yaw -= ci.x * 2.4 * dt * sens
		cam_pitch += ci.y * 1.6 * dt * sens * (-1.0 if G.settings.invert else 1.0)
		cam_idle = 0.0
	var td: Vector2 = hud.take_cam_drag()
	if td.length() > 0.0:
		cam_yaw -= td.x * 0.0055 * sens
		cam_pitch -= td.y * 0.0045 * sens * (-1.0 if G.settings.invert else 1.0)
		cam_idle = 0.0
	cam_pitch = clampf(cam_pitch, -1.25, 0.75)
	cam_idle += dt
	# auto-follow behind the hero when moving forward / flying
	var hv := Vector2(hero.velocity.x, hero.velocity.z).length()
	var follow := 0.0
	if hero.mode == "glide" or hero.mode == "rail":
		follow = 2.2
	elif hero.mode == "zip":
		follow = 1.4
	elif hv > 3.0 and cam_idle > 1.0 and inp.move.y > -0.3 and absf(inp.move.x) < 0.75:
		follow = 0.7
	if follow > 0.0 and cam_idle > 0.6:
		cam_yaw = lerp_angle(cam_yaw, hero.facing, 1.0 - exp(-follow * dt))
		if hero.mode == "glide" or hero.mode == "rail":
			cam_pitch = lerpf(cam_pitch, -0.22, 1.0 - exp(-1.2 * dt))
	var want_dist := 6.6
	if hero.mode == "glide" or hero.mode == "zip":
		want_dist = 8.8
	elif hero.mode == "rail":
		want_dist = 11.0
	if in_arena and titan != null and not titan.dead:
		want_dist += 3.0
	cam_dist = lerpf(cam_dist, want_dist, 1.0 - exp(-2.5 * dt))
	var tgt := hero.global_position + Vector3(0, 1.65, 0)
	cam_target = cam_target.lerp(tgt, 1.0 - exp(-14.0 * dt))
	if cam_target.distance_to(tgt) > 12.0:
		cam_target = tgt
	var d := Hero.fwd(cam_yaw) * cos(cam_pitch) + Vector3.UP * sin(cam_pitch)
	var want := cam_target - d * cam_dist + Vector3(0, 0.35, 0)
	# collision
	var space := hero.get_world_3d().direct_space_state
	var q := PhysicsRayQueryParameters3D.create(cam_target, want)
	q.exclude = [hero.get_rid()]
	var hit := space.intersect_ray(q)
	if not hit.is_empty():
		want = hit.position + (cam_target - want).normalized() * 0.4 + hit.normal * 0.2
	cam.global_position = want
	var sh := Vector3.ZERO
	if shake_amt > 0.0:
		sh = Vector3(randf_range(-1, 1), randf_range(-1, 1), randf_range(-1, 1)) * shake_amt * 0.35
		shake_amt = maxf(0.0, shake_amt - dt * 2.5)
	cam.look_at(cam_target + sh, Vector3.UP)
	var speed := hero.velocity.length()
	var fov_want := 70.0 + clampf((speed - 10.0) * 0.45, 0.0, 16.0)
	cam_fov = lerpf(cam_fov, fov_want, 1.0 - exp(-3.0 * dt))
	cam.fov = cam_fov


func shake(a: float) -> void:
	shake_amt = maxf(shake_amt, a)


# ------------------------------------------------------------------ helpers
func _in_updraft(p: Vector3) -> bool:
	for u in world.updrafts:
		var b: Vector3 = u.pos
		if Vector2(p.x - b.x, p.z - b.z).length() < float(u.r) + 0.6 and p.y > b.y - 1.0 and p.y < b.y + float(u.h) + 8.0:
			return true
	return false


func _seg_dist(a: Vector3, b: Vector3, c: Vector3) -> float:
	var ab := b - a
	var l2 := ab.length_squared()
	if l2 < 0.000001:
		return a.distance_to(c)
	var k := clampf((c - a).dot(ab) / l2, 0.0, 1.0)
	return (a + ab * k).distance_to(c)


func _los(a: Vector3, b: Vector3) -> bool:
	var space := hero.get_world_3d().direct_space_state
	var q := PhysicsRayQueryParameters3D.create(a, b)
	q.exclude = [hero.get_rid()]
	var hit := space.intersect_ray(q)
	return hit.is_empty() or hit.position.distance_to(b) < 1.5


func _find_hook() -> Dictionary:
	var range_v: float = float(G.up_val("hook"))
	var hc := hero.center()
	var cf := -cam.global_transform.basis.z
	cf = cf.normalized()
	var best: Dictionary = {}
	var best_s := 1e9
	var cands := []
	for a in world.anchors:
		var p: Vector3 = a.pos
		var to := p - hc
		var dist := to.length()
		if dist > range_v or dist < 3.0:
			continue
		var dir := to / dist
		var dot := dir.dot(cf)
		# flatten: also accept anchors the hero is moving towards
		var hd := Vector3(cf.x, 0, cf.z).normalized()
		var dot_h := Vector3(dir.x, 0, dir.z).normalized().dot(hd)
		if dot < 0.25 and dot_h < 0.55:
			continue
		var s := dist * (1.8 - maxf(dot, dot_h))
		if p.y < hc.y - 4.0:
			s *= 1.6
		cands.append([s, a])
	cands.sort_custom(func(x, y): return x[0] < y[0])
	for i in mini(3, cands.size()):
		var a: Dictionary = cands[i][1]
		if _los(hc, a.pos):
			best = a
			break
	return best


func _pick_target():
	var cpos := cam.global_position
	var cf := -cam.global_transform.basis.z
	var hc := hero.center()
	var best = null
	var best_s := 1e9
	var cands := []
	for d in drones:
		if d.dead or d.spawn_t < 1.0:
			continue
		cands.append([d, d.global_position])
	if titan != null:
		for w in titan.targets():
			cands.append([w, w.node.global_position])
	for p in projs:
		if p.kind == "missile" and not p.dead:
			cands.append([p, p.global_position])
	# 1) inside the camera cone
	for c in cands:
		var pos: Vector3 = c[1]
		var dist := hc.distance_to(pos)
		if dist > 75.0:
			continue
		var dir := (pos - cpos).normalized()
		var dot := dir.dot(cf)
		if dot < 0.84:
			continue
		var s := (1.0 - dot) * 120.0 + dist * 0.05
		if s < best_s:
			best_s = s
			best = c[0]
	if best != null:
		return best
	# 2) nearest threat around the hero (helps on touch)
	for c in cands:
		var pos: Vector3 = c[1]
		var dist := hc.distance_to(pos)
		if dist > 34.0:
			continue
		var dir := (pos - cpos).normalized()
		if dir.dot(cf) < -0.15:
			continue
		if dist < best_s:
			best_s = dist
			best = c[0]
	return best


func _target_pos(tg) -> Vector3:
	if tg is Drone:
		return tg.global_position
	if tg is Proj:
		return tg.global_position
	if tg is Dictionary:
		return tg.node.global_position
	return Vector3.ZERO


func _target_alive(tg) -> bool:
	if tg == null:
		return false
	if tg is Drone:
		return is_instance_valid(tg) and not tg.dead
	if tg is Proj:
		return is_instance_valid(tg) and not tg.dead
	if tg is Dictionary:
		return tg.alive and titan != null
	return false


# ------------------------------------------------------------------ combat
func _fire_bolt() -> void:
	var muzzle := hero.muzzle.global_position
	var dir: Vector3
	var tgt = aim_target
	if _target_alive(tgt):
		dir = (_target_pos(tgt) - muzzle).normalized()
	else:
		tgt = null
		var cf := -cam.global_transform.basis.z
		var aim_p := cam.global_position + cf * 90.0
		var space := hero.get_world_3d().direct_space_state
		var q := PhysicsRayQueryParameters3D.create(cam.global_position + cf * cam_dist, aim_p)
		q.exclude = [hero.get_rid()]
		var hit := space.intersect_ray(q)
		if not hit.is_empty():
			aim_p = hit.position
		dir = (aim_p - muzzle).normalized()
	hero.did_fire(dir)
	var p := Proj.new()
	fx_root.add_child(p)
	var gc: Color = G.PAINTS.get(G.data.paint, G.PAINTS.sky).glow
	if G.data.paint == "prism":
		gc = Color.from_hsv(fmod(t * 0.3, 1.0), 0.6, 1.0)
	p.setup("bolt", muzzle, dir * 78.0, gc)
	p.dmg = float(G.up_val("power"))
	p.target = tgt
	p.turn = 9.0 if tgt != null else 0.0
	projs.append(p)
	G.play("blaster", -7.0, randf_range(0.94, 1.08), 0.02)
	tip_done("fire")


func enemy_fire(d: Drone, kind: String, aim: Vector3, speed: float) -> void:
	var from := d.global_position
	var p := Proj.new()
	fx_root.add_child(p)
	match kind:
		"orb", "laser":
			var dir := (aim - from).normalized()
			p.setup(kind, from + dir * 1.2, dir * speed)
			p.target = null
			G.play_at("elaser", from, hero.global_position, -4.0, 1.3 if kind == "orb" else 1.0)
		"bomb":
			p.setup("bomb", from + Vector3(0, -1.0, 0), d.vel * 0.4 + Vector3(0, -3.0, 0))
			p.dmg = 2.0
			_bomb_marker(p)
			G.play_at("missile", from, hero.global_position, -6.0, 1.6)
	projs.append(p)


func _bomb_marker(p: Proj) -> void:
	var space := hero.get_world_3d().direct_space_state
	var q := PhysicsRayQueryParameters3D.create(p.global_position, p.global_position + Vector3(0, -80, 0))
	q.exclude = [hero.get_rid()]
	var hit := space.intersect_ray(q)
	if hit.is_empty():
		return
	var m := MeshInstance3D.new()
	m.mesh = Geo.torus(2.6, 3.2, 32, 4)
	var mat := StandardMaterial3D.new()
	mat.shading_mode = BaseMaterial3D.SHADING_MODE_UNSHADED
	mat.albedo_color = Color(1.0, 0.25, 0.2, 0.7)
	mat.transparency = BaseMaterial3D.TRANSPARENCY_ALPHA
	m.material_override = mat
	m.scale = Vector3(1, 0.1, 1)
	fx_root.add_child(m)
	m.global_position = hit.position + Vector3(0, 0.1, 0)
	p.set_meta("marker", m)


func _update_projs(dt: float) -> void:
	var space := hero.get_world_3d().direct_space_state
	var hc := hero.center()
	var keep: Array = []
	for p in projs:
		if p.dead or not is_instance_valid(p):
			continue
		var aim = null
		if p.hostile and p.kind == "missile":
			aim = hc
		elif not p.hostile and p.target != null:
			if _target_alive(p.target):
				aim = _target_pos(p.target)
			else:
				p.target = null
		var a: Vector3 = p.global_position
		p.step(dt, aim)
		var b: Vector3 = p.global_position
		var done := false
		if not p.hostile:
			for d in drones:
				if d.dead:
					continue
				if _seg_dist(a, b, d.global_position) < d.radius + p.radius:
					_spark(b, Color(0.6, 0.9, 1.0))
					G.play_at("hit", b, hero.global_position, -6.0, randf_range(0.9, 1.2))
					if d.hit(p.dmg):
						_drone_down(d)
					done = true
					break
			if not done:
				for q in projs:
					if q.kind == "missile" and not q.dead and _seg_dist(a, b, q.global_position) < 1.3:
						q.dead = true
						explode(q.global_position, 1.2, false)
						done = true
						break
			if not done and titan != null and not titan.dead:
				for w in titan.weak:
					if not w.alive:
						continue
					var wp: Vector3 = w.node.global_position
					if _seg_dist(a, b, wp) < float(w.r):
						if w.phase == titan.phase and (w.phase != 3 or titan.open_t > 0.0):
							titan.hit_weak(w, p.dmg)
							_spark(b, Color(0.7, 0.95, 1.0))
							G.play_at("hit", b, hero.global_position, -2.0, 0.8)
							hud.hit_marker()
						else:
							_spark(b, Color(0.7, 0.5, 1.0))
							G.play_at("shield", b, hero.global_position, -8.0, 1.4)
						done = true
						break
		else:
			if hero.mode != "down" and _seg_dist(a, b, hc) < p.radius + 0.55:
				if p.kind == "bomb" or p.kind == "missile":
					_area_blast(b, p)
				else:
					hero.take_hit(int(p.dmg), b)
					_spark(b, Color(1.0, 0.4, 0.3))
				done = true
		if not done:
			var q := PhysicsRayQueryParameters3D.create(a, b)
			q.exclude = [hero.get_rid()]
			var hit := space.intersect_ray(q)
			if not hit.is_empty():
				if p.kind == "bomb" or p.kind == "missile":
					_area_blast(hit.position, p)
				else:
					_spark(hit.position, Color(0.6, 0.9, 1.0) if not p.hostile else Color(1.0, 0.4, 0.3))
				done = true
		if p.life <= 0.0:
			if p.kind == "missile" or p.kind == "bomb":
				_area_blast(p.global_position, p)
			done = true
		if done:
			p.dead = true
			if p.has_meta("marker"):
				var m = p.get_meta("marker")
				if is_instance_valid(m):
					m.queue_free()
			p.queue_free()
		else:
			if p.has_meta("marker"):
				var m: MeshInstance3D = p.get_meta("marker")
				if is_instance_valid(m):
					m.rotate_y(dt * 3.0)
					var s := 0.8 + sin(t * 14.0) * 0.15
					m.scale = Vector3(s, 0.1, s)
			keep.append(p)
	projs = keep


func _area_blast(pos: Vector3, p: Proj) -> void:
	explode(pos, 1.6, false)
	if hero.center().distance_to(pos) < 3.4:
		hero.take_hit(int(maxf(1.0, p.dmg)), pos)


func _drone_down(d: Drone) -> void:
	explode(d.global_position, 1.3 if d.kind == "scout" else 1.8, false)
	var n := 3 if d.kind == "scout" else 5
	for i in n:
		_spawn_loot(d.global_position)
	G.data.drones = int(G.data.drones) + 1
	dirty = true


func _update_drones(dt: float) -> void:
	var keep := []
	for d in drones:
		if not is_instance_valid(d):
			continue
		if d.dead:
			d.queue_free()
			continue
		d.update(dt, hero, t)
		keep.append(d)
	drones = keep


func spawn_drone(kind: String, pos: Vector3, tag: String = "") -> Drone:
	var d := Drone.new()
	fx_root.add_child(d)
	d.setup(kind, pos, self)
	d.tag = tag
	drones.append(d)
	G.play_at("hum", pos, hero.global_position, -10.0)
	tip("fire", "Drones! Press FIRE to blast them. Your shots lock on automatically.")
	return d


# ------------------------------------------------------------------ fx
func _fx_mat(c: Color, add: bool = true) -> StandardMaterial3D:
	var m := StandardMaterial3D.new()
	m.shading_mode = BaseMaterial3D.SHADING_MODE_UNSHADED
	m.billboard_mode = BaseMaterial3D.BILLBOARD_PARTICLES
	m.albedo_color = c
	m.transparency = BaseMaterial3D.TRANSPARENCY_ALPHA
	if add:
		m.blend_mode = BaseMaterial3D.BLEND_MODE_ADD
	m.vertex_color_use_as_albedo = true
	return m


func _burst(pos: Vector3, amount: int, color: Color, speed: float, size: float, life: float, grav: float = -9.0, add: bool = true) -> void:
	var p := CPUParticles3D.new()
	p.one_shot = true
	p.explosiveness = 0.95
	p.amount = amount
	p.lifetime = life
	p.direction = Vector3.UP
	p.spread = 180.0
	p.initial_velocity_min = speed * 0.4
	p.initial_velocity_max = speed
	p.gravity = Vector3(0, grav, 0)
	p.scale_amount_min = size * 0.5
	p.scale_amount_max = size
	var curve := Curve.new()
	curve.add_point(Vector2(0, 1))
	curve.add_point(Vector2(1, 0))
	p.scale_amount_curve = curve
	var qm := QuadMesh.new()
	qm.size = Vector2(1, 1)
	qm.material = _fx_mat(color, add)
	p.mesh = qm
	p.local_coords = false
	fx_root.add_child(p)
	p.global_position = pos
	p.emitting = true
	get_tree().create_timer(life + 0.3).timeout.connect(p.queue_free)


func _spark(pos: Vector3, c: Color) -> void:
	_burst(pos, 10, c, 7.0, 0.25, 0.35, -6.0)


func explode(pos: Vector3, size: float, big: bool) -> void:
	_burst(pos, int(18 * size) + 8, Color(1.0, 0.7, 0.3), 9.0 * size, 0.9 * size, 0.6)
	_burst(pos, int(8 * size) + 4, Color(0.75, 0.45, 1.0), 6.0 * size, 1.2 * size, 0.8)
	_burst(pos, 8, Color(0.35, 0.33, 0.38, 0.6), 3.0 * size, 2.2 * size, 1.4, 1.5, false)
	var l := OmniLight3D.new()
	l.light_color = Color(1.0, 0.7, 0.4)
	l.light_energy = 6.0 * size
	l.omni_range = 6.0 * size + 4.0
	fx_root.add_child(l)
	l.global_position = pos
	var tw := create_tween()
	tw.tween_property(l, "light_energy", 0.0, 0.5)
	tw.tween_callback(l.queue_free)
	# metal scrap
	for i in int(3 + size * 2):
		var m := MeshInstance3D.new()
		m.mesh = Geo.box(Vector3(randf_range(0.15, 0.45), randf_range(0.08, 0.25), randf_range(0.15, 0.4)) * size)
		m.material_override = G.mats.get("dark_metal")
		fx_root.add_child(m)
		m.global_position = pos
		debris.append({"n": m, "v": Vector3(randf_range(-1, 1), randf_range(0.4, 1.5), randf_range(-1, 1)) * 9.0 * sqrt(size), "w": Vector3(randf(), randf(), randf()).normalized(), "life": 2.2})
	var d := hero.global_position.distance_to(pos)
	G.play("bigboom" if big else "boom", lerpf(-2.0, -16.0, clampf(d / 80.0, 0.0, 1.0)), randf_range(0.9, 1.1), 0.05)
	shake((0.6 if big else 0.25) * clampf(1.0 - d / 60.0, 0.0, 1.0))


func _spawn_loot(pos: Vector3) -> void:
	var m := MeshInstance3D.new()
	m.mesh = world.mesh_shard
	var sm := ShaderMaterial.new()
	sm.shader = load("res://shaders/shard.gdshader")
	m.material_override = sm
	m.scale = Vector3.ONE * 0.8
	fx_root.add_child(m)
	m.global_position = pos
	loot.append({"n": m, "v": Vector3(randf_range(-1, 1), randf_range(0.5, 1.2), randf_range(-1, 1)) * 7.0, "t": 0.0})


func _update_loot(dt: float) -> void:
	var keep := []
	var hc := hero.center()
	for l in loot:
		var n: MeshInstance3D = l.n
		l.t += dt
		if l.t < 0.45:
			l.v.y -= 14.0 * dt
			n.global_position += l.v * dt
		else:
			var to: Vector3 = hc - n.global_position
			var sp: float = 10.0 + l.t * 30.0
			n.global_position += to.normalized() * minf(sp * dt, to.length())
			if to.length() < 0.8:
				n.queue_free()
				_add_shards(1)
				continue
		keep.append(l)
	loot = keep
	var dk := []
	for d in debris:
		d.life -= dt
		var n: MeshInstance3D = d.n
		if d.life <= 0.0:
			n.queue_free()
			continue
		d.v.y -= 20.0 * dt
		n.global_position += d.v * dt
		n.rotate(d.w, dt * 8.0)
		dk.append(d)
	debris = dk


func _add_shards(n: int) -> void:
	G.data.shards = int(G.data.shards) + n
	shard_combo_t = 1.2
	shard_combo += 1
	G.play("shard", -9.0, 1.0 + minf(shard_combo, 16) * 0.04, 0.03)
	hud.pulse_shards()
	dirty = true


func _collect_shards() -> void:
	shard_combo_t -= get_physics_process_delta_time()
	if shard_combo_t <= 0.0:
		shard_combo = 0
	var hc := hero.center()
	var sp: PackedVector3Array = world.shard_pos
	var alive: PackedByteArray = world.shard_alive
	for i in sp.size():
		if alive[i] == 0:
			continue
		if sp[i].distance_squared_to(hc) < 3.6:
			world.take_shard(i)
			G.bit_set("shard_bits", i)
			_add_shards(1)
			_burst(sp[i], 6, Color(0.5, 0.9, 1.0), 3.0, 0.2, 0.3, 0.0)
	for i in world.prism_pos.size():
		var n: Node3D = world.prism_nodes[i]
		if n.visible and world.prism_pos[i].distance_to(hc) < 2.4:
			n.visible = false
			G.bit_set("prism_bits", i)
			G.data.shards = int(G.data.shards) + 10
			G.play("core", -6.0, 1.4)
			_burst(world.prism_pos[i], 30, Color(1.0, 0.6, 0.9), 6.0, 0.4, 0.7, 0.0)
			hud.toast("PRISM SHARD! +10")
			hud.pulse_shards()
			dirty = true


# ------------------------------------------------------------------ world interactions
func _check_pads(dt: float) -> void:
	pad_cool = maxf(0.0, pad_cool - dt)
	if hero.mode != "ground" or pad_cool > 0.0:
		return
	var hp := hero.global_position
	for p in world.pads:
		var pp: Vector3 = p.pos
		if Vector2(hp.x - pp.x, hp.z - pp.z).length() < 2.5 and hp.y > pp.y - 0.6 and hp.y < pp.y + 2.2:
			hero.start_rail(hp, p.dest, p.name)
			pad_cool = 2.0
			if ring.active:
				_ring_fail(false)
			tip_done("pad")
			return
	# tip when near a pad
	for p in world.pads:
		if hp.distance_to(p.pos) < 9.0:
			tip("pad", "Step onto a LAUNCH PAD to fly to its island!")
			break


func on_rail_done(_h) -> void:
	pad_cool = 1.2
	shake(0.2)
	var best: Dictionary = {}
	var bd := 45.0
	for c in world.checkpoints:
		var d: float = hero.global_position.distance_to(c.pos)
		if d < bd:
			bd = d
			best = c
	if not best.is_empty():
		_set_checkpoint(best, false)
	# island arrival banner
	var isl := _island_of(hero.global_position)
	if isl >= 0 and isl != current_island:
		hud.banner(G.ISLAND_NAMES[isl], _island_hint(isl), Color(0.75, 0.95, 1.0))
		G.data.visited[isl] = true
	elif isl == -1 and _dist_h(hero.global_position, world.HUB) < 60:
		hud.banner("HAVEN", "Home island. The Forge and the Storm Gate are here.", Color(1.0, 0.9, 0.6))
	current_island = isl
	dirty = true


func _dist_h(a: Vector3, b: Vector3) -> float:
	return Vector2(a.x - b.x, a.z - b.z).length()


func _island_of(p: Vector3) -> int:
	var centers := [Vector3(0, 0, -195), world.L2 + Vector3(90, 0, 0), world.L3, world.L4 + Vector3(-90, 0, 60), world.C5 + Vector3(20, 0, 20)]
	var radii := [75.0, 110.0, 60.0, 140.0, 70.0]
	for i in 5:
		if _dist_h(p, centers[i]) < radii[i]:
			return i
	if _dist_h(p, world.ARENA) < 90.0:
		return 9
	return -1


func _island_hint(i: int) -> String:
	if i == 9:
		return "Defeat the Storm Titan!"
	if G.data.cores[i]:
		return "Core already recovered. Explore for shards!"
	return ["Jump up the spiral stones to the core at the top!", "Zip across the gaps: press HOOK at the blue rings!", "Clear 3 waves of drones to free the core!", "Glide through every ring before the timer ends!", "Climb the crystal: lifts, hooks and drone guards!"][i]


func _check_checkpoints() -> void:
	var hp := hero.global_position
	for c in world.checkpoints:
		if c == checkpoint:
			continue
		var cp: Vector3 = c.pos
		if Vector2(hp.x - cp.x, hp.z - cp.z).length() < 2.6 and absf(hp.y - cp.y) < 3.0:
			_set_checkpoint(c, true)


func _set_checkpoint(c: Dictionary, announce: bool) -> void:
	if c == checkpoint:
		return
	checkpoint = c
	world.set_checkpoint_on(c, true)
	if announce:
		G.play("checkpoint", -4.0)
		hud.toast("CHECKPOINT")


func _check_cores() -> void:
	var hc := hero.center()
	for i in world.cores.size():
		var c: Dictionary = world.cores[i]
		if not c.active or not c.orb.visible:
			continue
		if hc.distance_to(c.pos) < 2.8:
			_collect_core(i)


func _collect_core(i: int) -> void:
	G.data.cores[i] = true
	world.set_core_taken(i)
	G.data.shards = int(G.data.shards) + 50
	var n := G.cores_count()
	G.play("core", 0.0)
	_burst(world.cores[i].pos, 60, Color(0.5, 0.95, 1.0), 10.0, 0.5, 1.0, 0.0)
	shake(0.3)
	world.update_gate(G.data.cores, n >= 5)
	if n >= 5:
		hud.banner("ALL 5 STORM CORES!", "The STORM GATE in Haven is open. Time to face the Titan!", Color(0.8, 0.6, 1.0))
	else:
		hud.banner("STORM CORE %d/5" % n, "+50 shards. %d more to open the Storm Gate." % (5 - n), Color(0.5, 0.95, 1.0))
	G.save_game()


func _update_context() -> void:
	context = ""
	var hp := hero.global_position
	if hp.distance_to(world.forge_pos) < 8.0:
		context = "FORGE"
	elif hp.distance_to(world.gate_pos) < 9.0:
		if G.cores_count() >= 5:
			context = "ENTER STORM" if not G.data.boss else "REMATCH"
		else:
			gate_hint_t -= get_physics_process_delta_time()
			if gate_hint_t <= 0.0:
				gate_hint_t = 6.0
				hud.toast("STORM GATE: %d/5 cores. Find them all!" % G.cores_count())
	if inp.interact_pressed:
		match context:
			"FORGE":
				open_forge()
			"ENTER STORM", "REMATCH":
				enter_arena()


func _check_fall() -> void:
