func glide_assist(h: Hero) -> Vector3:
	if not G.settings.assist:
		return Vector3.ZERO
	if ring.done or world.rings.is_empty():
		return Vector3.ZERO
	var idx: int = ring.idx
	if idx >= world.rings.size():
		return Vector3.ZERO
	var r: Dictionary = world.rings[idx]
	var to: Vector3 = r.pos - h.center()
	var hd := Vector2(to.x, to.z).length()
	if hd > 48.0 or hd < 1.5:
		return Vector3.ZERO
	var head := h.glide_heading
	var dirh := Vector3(to.x, 0, to.z) / hd
	if head.dot(dirh) < 0.55:
		return Vector3.ZERO
	var hs := maxf(8.0, Vector2(h.velocity.x, h.velocity.z).length())
	var vy := clampf(to.y / (hd / hs), -10.0, 8.0)
	var out := Vector3(0, vy, 0)
	if hd < 30.0:
		out.x = dirh.x
		out.z = dirh.z
	return out


# ------------------------------------------------------------------ missions
func _update_foundry(dt: float) -> void:
	if G.data.cores[2]:
		return
	var center: Vector3 = world.cores[2].pos - Vector3(0, 3.0, 0)
	var d := hero.global_position.distance_to(center)
	match foundry.state:
		"idle":
			if d < 24.0 and hero.mode != "rail":
				foundry.wave = 0
				_foundry_next()
		"wave":
			var left := 0
			for dr in drones:
				if dr.tag == "foundry" and not dr.dead:
					left += 1
			foundry["left"] = left
			if left == 0:
				if foundry.wave >= 3:
					foundry.state = "done"
					world.set_core_visible(2, true)
					var orb: Node3D = world.cores[2].orb
					var base := orb.position
					orb.position = base - Vector3(0, 4, 0)
					create_tween().tween_property(orb, "position", base, 2.0).set_trans(Tween.TRANS_BACK).set_ease(Tween.EASE_OUT)
					hud.banner("FOUNDRY CLEARED!", "The Storm Core is free. Grab it!", Color(1.0, 0.75, 0.4))
					G.play("victory", -4.0)
				else:
					foundry.state = "break"
					foundry.timer = 2.5
					hud.toast("WAVE %d CLEARED!" % foundry.wave)
		"break":
			foundry.timer -= dt
			if foundry.timer <= 0.0:
				_foundry_next()
	if (foundry.state == "wave" or foundry.state == "break") and d > 80.0:
		for dr in drones:
			if dr.tag == "foundry":
				dr.dead = true
		foundry.state = "idle"
		foundry.wave = 0
		hud.toast("You left the Foundry. The waves reset.")


func _foundry_next() -> void:
	foundry.wave += 1
	foundry.state = "wave"
	var kinds := []
	match int(foundry.wave):
		1:
			kinds = ["scout", "scout", "scout", "scout"]
		2:
			kinds = ["scout", "scout", "scout", "gunner", "gunner"]
		_:
			kinds = ["gunner", "gunner", "bomber", "bomber", "scout", "scout"]
	var sp: Array = world.foundry_spawns
	for i in kinds.size():
		var p: Vector3 = sp[i % sp.size()] + Vector3(randf_range(-2, 2), randf_range(0, 3), randf_range(-2, 2))
		spawn_drone(kinds[i], p, "foundry")
	foundry["left"] = kinds.size()
	hud.banner("WAVE %d OF 3" % foundry.wave, "Drones incoming!", Color(1.0, 0.5, 0.4))
	G.play("warn", -4.0)


func _update_rings(dt: float) -> void:
	var rings: Array = world.rings
	if rings.is_empty():
		return
	var hp := hero.center()
	var pp := prev_hero_pos + Vector3(0, 1.0, 0)
	var idx: int = ring.idx
	if idx < rings.size():
		var r: Dictionary = rings[idx]
		var n: Vector3 = r.normal
		var s0: float = (pp - r.pos).dot(n)
		var s1: float = (hp - r.pos).dot(n)
		if (s0 < 0.0 and s1 >= 0.0) or (s0 > 0.0 and s1 <= 0.0):
			var k: float = s0 / (s0 - s1) if absf(s0 - s1) > 0.0001 else 0.0
			var ip := pp.lerp(hp, k)
			if ip.distance_to(r.pos) < 5.0:
				_ring_pass(idx)
		elif hp.distance_to(r.pos) < 3.2:
			_ring_pass(idx)
	if ring.active:
		ring.time -= dt
		ring.elapsed += dt
		if ring.time <= 0.0:
			_ring_fail(false)
	# visuals
	for i in rings.size():
		var r: Dictionary = rings[i]
		var m: StandardMaterial3D = r.mat
		var e := 0.6
		var sc := 1.0
		if ring.done:
			e = 1.2
		elif i < ring.idx:
			e = 0.15
		elif i == ring.idx:
			e = 4.0 + sin(t * 6.0) * 1.0
			sc = 1.0 + sin(t * 4.0) * 0.04
		elif i == ring.idx + 1:
			e = 1.6
		m.emission_energy_multiplier = e
		(r.node as Node3D).scale = Vector3.ONE * sc
		(r.film as MeshInstance3D).visible = i == ring.idx and not ring.done


func _ring_pass(i: int) -> void:
	var r: Dictionary = world.rings[i]
	if i == 0 and not ring.active:
		ring.active = true
		ring.time = 16.0
		ring.elapsed = 0.0
		hud.toast("GO! Fly through every ring!")
	ring.idx = i + 1
	ring.time += 6.0
	G.play("ring", -3.0, 1.0 + i * 0.05)
	_burst(r.pos, 24, r.col, 8.0, 0.4, 0.5, 0.0)
	if r.boost:
		hero.velocity.y = 17.0
		hud.toast("BOOST!")
		G.play("dash", -4.0, 1.3)
	elif hero.mode == "glide":
		hero.velocity.y = maxf(hero.velocity.y, 4.5)
	if ring.idx >= world.rings.size():
		ring.active = false
		var first: bool = not ring.done
		ring.done = true
		var tm: float = ring.elapsed
		var best: float = float(G.data.ring_best)
		if best <= 0.0 or tm < best:
			G.data.ring_best = tm
		if not G.data.cores[3]:
			world.set_core_visible(3, true)
			hud.banner("RING MASTER!", "Time %.1f s. Land on the island ahead and grab the core!" % tm, Color(1.0, 0.85, 0.35))
		else:
			hud.banner("RING RUN COMPLETE", "Time %.1f s  (best %.1f s)" % [tm, float(G.data.ring_best)], Color(1.0, 0.85, 0.35))
		G.play("victory", -4.0)
		dirty = true


func _ring_fail(fell: bool) -> void:
	ring.active = false
	ring.idx = 0
	hud.banner("OUT OF TIME!" if not fell else "RING RUN FAILED", "Fly back to the tower and start again at the first ring.", Color(1.0, 0.6, 0.4))
	G.play("deny", -4.0)


func _update_spire() -> void:
	var d := hero.global_position.distance_to(world.C5 + Vector3(0, 30, 0))
	if G.data.cores[4]:
		return
	if not spire_spawned and d < 80.0:
		spire_spawned = true
		for gp in world.spire_guards:
			var dr := spawn_drone("gunner", gp, "spire")
			dr.guard = true
			dr.guard_pos = gp
	elif spire_spawned and d > 170.0:
		spire_spawned = false
		for dr in drones:
			if dr.tag == "spire":
				dr.dead = true


