func enter_arena() -> void:
	hud.flash(Color(0.7, 0.5, 1.0, 1.0))
	G.play("respawn", 0.0, 0.7)
	for c in world.checkpoints:
		if c.get("arena", false):
			_set_checkpoint(c, false)
	hero.respawn_at(checkpoint.pos + Vector3(7.0, 1.2, 5.0), PI)
	hero.facing = PI
	hero.hearts = hero.max_hearts
	cam_yaw = PI
	cam_pitch = -0.06
	cam_target = hero.global_position
	in_arena = true
	current_island = 9
	boss_time = 0.0
	if titan != null and is_instance_valid(titan):
		titan.queue_free()
	titan = Titan.new()
	fx_root.add_child(titan)
	var center: Vector3 = world.ARENA
	var d: Geo.IslandData = world.islands.filter(func(x): return x.pos == world.ARENA)[0].data
	titan.setup(self, center + Vector3(0, d.top_h(0, 0), 0))
	titan.yaw = 0.0
	G.music("music_boss")
	hud.banner("THE STORM TITAN", "Shoot its glowing cores! Jump over the shockwaves!", Color(0.8, 0.55, 1.0))
	G.data.boss_tries = int(G.data.boss_tries) + 1
	for dr in drones:
		dr.dead = true


func leave_arena() -> void:
	in_arena = false
	if titan != null and is_instance_valid(titan) and not titan.dead:
		titan.queue_free()
	titan = null
	for dr in drones:
		if dr.tag == "titan":
			dr.dead = true
	for w in shockwaves:
		w.n.queue_free()
	shockwaves.clear()
	for s in strikes:
		s.n.queue_free()
	strikes.clear()
	for c in world.checkpoints:
		if c.get("hub", false):
			_set_checkpoint(c, false)
	hero.respawn_at(world.gate_pos + Vector3(0, 1.5, -8), 0.0)
	cam_yaw = 0.0
	hero.hearts = hero.max_hearts
	G.music("music_explore")
	hud.flash(Color(1, 1, 1, 1))
	current_island = -1
	hud.show_boss(false)


