func titan_slam(p: Vector3, phase: int) -> void:
	G.play("shock", 0.0)
	shake(0.8)
	explode(p, 2.0, false)
	_shockwave(p, 22.0 + phase * 2.0)
	if phase >= 3:
		get_tree().create_timer(0.55).timeout.connect(func(): if titan != null: _shockwave(p, 26.0))
	tip("shock", "JUMP over the purple shockwave rings!")


func _shockwave(p: Vector3, speed: float) -> void:
	var m := MeshInstance3D.new()
	var tm := Geo.torus(0.92, 1.0, 64, 6)
	m.mesh = tm
	m.material_override = world.energy_mat(Color(0.75, 0.3, 1.0), 1.3, 1.0, 2.0, 0.0, 0.0)
	fx_root.add_child(m)
	m.global_position = p + Vector3(0, 0.4, 0)
	var wall := MeshInstance3D.new()
	var cm := Geo.cyl(1.0, 1.0, 1.4, 64)
	cm.cap_top = false
	cm.cap_bottom = false
	wall.mesh = cm
	wall.material_override = world.energy_mat(Color(0.7, 0.3, 1.0), 0.9, 2.0, 3.0, 1.0, 0.0)
	m.add_child(wall)
	wall.position = Vector3(0, 0.3, 0)
	shockwaves.append({"n": m, "wall": wall, "c": p, "r": 2.0, "speed": speed, "max": 62.0, "hit": false})


func _update_waves(dt: float) -> void:
	var keep := []
	var hp := hero.global_position
	for w in shockwaves:
		w.r += w.speed * dt
		var n: MeshInstance3D = w.n
		n.scale = Vector3(w.r, 1.6, w.r)
		(w.wall as MeshInstance3D).scale = Vector3(1, 1.0 / 1.6, 1)
		var dh := _dist_h(hp, w.c)
		if not w.hit and absf(dh - w.r) < 1.3 and hp.y - w.c.y < 1.5 and hero.mode != "rail":
			if hero.take_hit(2, w.c):
				w.hit = true
		if w.r > w.max:
			n.queue_free()
			continue
		keep.append(w)
	shockwaves = keep


