	p.turn = 1.25 + titan.phase * 0.25
	p.dmg = 1.0
	p.life = 8.0
	projs.append(p)
	G.play_at("missile", pos, hero.global_position, -2.0, randf_range(0.9, 1.1))
	tip("missile", "Shoot the missiles down before they reach you!")


func titan_lightning(h: Hero, n: int) -> void:
	for i in n:
		var off := Vector3.ZERO if i == 0 else Vector3(randf_range(-9, 9), 0, randf_range(-9, 9))
		var p := h.global_position + off + Vector3(h.velocity.x, 0, h.velocity.z) * 0.5
		var space := h.get_world_3d().direct_space_state
		var q := PhysicsRayQueryParameters3D.create(p + Vector3(0, 30, 0), p + Vector3(0, -40, 0))
		q.exclude = [h.get_rid()]
		var hit := space.intersect_ray(q)
		if hit.is_empty():
			continue
		var m := MeshInstance3D.new()
		m.mesh = Geo.torus(2.9, 3.4, 40, 4)
		var mat := StandardMaterial3D.new()
		mat.shading_mode = BaseMaterial3D.SHADING_MODE_UNSHADED
		mat.albedo_color = Color(0.85, 0.75, 1.0, 0.8)
		mat.transparency = BaseMaterial3D.TRANSPARENCY_ALPHA
		m.material_override = mat
		m.scale = Vector3(1, 0.1, 1)
		fx_root.add_child(m)
		m.global_position = hit.position + Vector3(0, 0.12, 0)
		strikes.append({"n": m, "p": hit.position, "t": 1.4 + i * 0.12, "struck": false, "bolt": null})
	G.play("warn", -4.0, 1.5)
	tip("lightning", "Lightning! Get out of the glowing circles!")


func _update_strikes(dt: float) -> void:
	var keep := []
	for s in strikes:
		s.t -= dt
		var n: MeshInstance3D = s.n
		if not s.struck:
			var k := clampf(1.0 - s.t / 1.4, 0.0, 1.0)
			n.scale = Vector3(1.0 - k * 0.3, 0.1, 1.0 - k * 0.3)
			n.rotate_y(dt * 2.0)
			if s.t <= 0.0:
				s.struck = true
				s.t = 0.35
				_bolt_visual(s)
				G.play("thunder", -3.0, randf_range(0.9, 1.2), 0.08)
				_burst(s.p, 20, Color(0.8, 0.8, 1.0), 8.0, 0.4, 0.4)
				world.flash = 1.0
				var hp := hero.global_position
				if _dist_h(hp, s.p) < 3.4 and hp.y - s.p.y < 5.0:
					hero.take_hit(2, s.p)
		else:
			if s.t <= 0.0:
				n.queue_free()
				if s.bolt != null:
					s.bolt.queue_free()
				continue
		keep.append(s)
	strikes = keep


func _bolt_visual(s: Dictionary) -> void:
	var pts := PackedVector3Array()
	var p: Vector3 = s.p + Vector3(0, 70, 0)
	for i in 14:
		pts.append(p)
		p = p.lerp(s.p, 1.0 / float(14 - i)) + Vector3(randf_range(-1.5, 1.5), 0, randf_range(-1.5, 1.5)) * (1.0 if i < 13 else 0.0)
	pts.append(s.p)
	var m := MeshInstance3D.new()
	m.mesh = Geo.tube(pts, 0.18, 5)
	var mat := StandardMaterial3D.new()
	mat.shading_mode = BaseMaterial3D.SHADING_MODE_UNSHADED
	mat.albedo_color = Color(0.9, 0.9, 1.0)
	mat.emission_enabled = true
	mat.emission = Color(0.8, 0.8, 1.0)
	mat.emission_energy_multiplier = 8.0
	m.material_override = mat
	fx_root.add_child(m)
	s.bolt = m


