# ------------------------------------------------------------------ forge actions
func buy_upgrade(key: String) -> bool:
	var lv: int = int(G.data.up[key])
	var costs: Array = G.UPGRADES[key].costs
	if lv >= costs.size():
		return false
	var c: int = costs[lv]
	if int(G.data.shards) < c:
		G.play("deny", -4.0)
		return false
	G.data.shards = int(G.data.shards) - c
	G.data.up[key] = lv + 1
	G.play("buy", -2.0)
	G.play("anvil", -4.0, 1.2)
	hero.refresh_stats()
	if key == "hearts":
		hero.hearts = hero.max_hearts
	G.save_game()
	return true


func buy_paint(key: String) -> bool:
	if key in G.data.paints:
		G.data.paint = key
		hero.apply_paint(key)
		G.play("select", -4.0)
		G.save_game()
		return true
	var c: int = int(G.PAINTS[key].cost)
	if c < 0 or int(G.data.shards) < c:
		G.play("deny", -4.0)
		return false
	G.data.shards = int(G.data.shards) - c
	G.data.paints.append(key)
	G.data.paint = key
	hero.apply_paint(key)
	G.play("buy", -2.0)
	G.save_game()
	return true


func set_quality(q: String) -> void:
	G.settings.quality = q
	world.apply_quality(q)
	G.save_game()


func reset_progress() -> void:
	G.reset_game()
	get_tree().reload_current_scene()


func return_to_haven() -> void:
	if in_arena:
		leave_arena()
	else:
		for c in world.checkpoints:
			if c.get("hub", false):
				_set_checkpoint(c, false)
		_respawn(false)
		hud.flash(Color(1, 1, 1, 1))
	if ring.active:
		_ring_fail(true)
	resume()


