func objective() -> Dictionary:
	# {text, pos (or null)}
	if in_arena:
		if titan != null and not titan.dead:
			return {"text": "Defeat the Storm Titan", "pos": null}
		if not arena_return_pad.is_empty():
			return {"text": "The sky is free! Take the pad back to Haven", "pos": arena_return_pad.pos}
	var n := G.cores_count()
	if n >= 5:
		if G.data.boss:
			return {"text": "Free roam: find every shard and prism", "pos": null}
		return {"text": "Enter the STORM GATE in Haven", "pos": world.gate_pos + Vector3(0, 6, 0)}
	var nxt := -1
	for i in 5:
		if not G.data.cores[i]:
			nxt = i
			break
	var isl := _island_of(hero.global_position)
	if isl >= 0 and isl < 5 and not G.data.cores[isl]:
		nxt = isl
	var name: String = G.ISLAND_NAMES[nxt]
	if isl == nxt:
		var c: Dictionary = world.cores[nxt]
		if nxt == 2 and not c.orb.visible:
			var left: int = int(foundry.get("left", 0))
			if foundry.state == "wave":
				return {"text": "Wave %d/3: blast the drones (%d left)" % [foundry.wave, left], "pos": null}
			return {"text": "Step into the Foundry arena", "pos": c.pos}
		if nxt == 3 and not c.orb.visible:
			if ring.active:
				return {"text": "Next ring!  %d/%d" % [ring.idx, world.rings.size()], "pos": world.rings[mini(ring.idx, world.rings.size() - 1)].pos}
			return {"text": "Climb the tower, then glide through ring 1", "pos": world.rings[0].pos}
		return {"text": "Grab the Storm Core of " + name, "pos": c.pos}
	for p in world.pads:
		if p.has("island") and p.island == nxt:
			if _dist_h(hero.global_position, world.HUB) < 70.0:
				return {"text": "Next: %s  (take its launch pad)" % name, "pos": p.pos + Vector3(0, 2, 0)}
	return {"text": "Next: %s  (go back to Haven)" % name, "pos": null}


