# ------------------------------------------------------------------ self-test bot
func log_t(s: String) -> void:
	print("[selftest] ", s)
	test_log.append(s)


func wait(sec: float) -> void:
	await get_tree().create_timer(sec, true, true).timeout


func wait_until(cond: Callable, timeout: float) -> bool:
	var tt := 0.0
	while tt < timeout:
		if cond.call():
			return true
		await get_tree().physics_frame
		tt += get_physics_process_delta_time()
	return false


func run_selftest() -> void:
	G.data = G.default_data()
	G.data.seen_intro = true
	await get_tree().process_frame
	start_play()
	var fails := 0
	var ok := func(name: String, cond: bool):
		log_t(("PASS " if cond else "FAIL ") + name)
		return cond
	bot = {"move": Vector2.ZERO}
	await wait(1.0)
	if not ok.call("hero on the hub floor", hero.is_on_floor()):
		fails += 1
	# run forward
	var p0 := hero.global_position
	bot.move = Vector2(0, 1)
	await wait(1.0)
	bot.move = Vector2.ZERO
	if not ok.call("running moves the hero (%.1f m)" % p0.distance_to(hero.global_position), p0.distance_to(hero.global_position) > 5.0):
		fails += 1
	# jump + double jump + glide
	bot.jump_pressed = true
	bot.jump_held = true
	await wait(0.35)
	bot.jump_pressed = true
	await wait(1.6)
	var glided: float = hero.stats.glide_time
	bot.jump_held = false
	if not ok.call("double jump done", hero.stats.jump2 >= 1):
		fails += 1
	await wait_until(func(): return hero.is_on_floor(), 6.0)
	# glide from height
	hero.respawn_at(world.HUB + Vector3(0, 30, 0), 0.0)
	hero.jumps = 2
	bot.jump_held = true
	bot.move = Vector2(0, 1)
	await wait(2.0)
	if not ok.call("glide works (%.1f s gliding, vy %.1f)" % [hero.stats.glide_time, hero.velocity.y], hero.stats.glide_time > 1.0 and hero.velocity.y > -7.0):
		fails += 1
	bot.jump_held = false
	bot.move = Vector2.ZERO
	await wait_until(func(): return hero.is_on_floor(), 8.0)
	# dash
	bot.dash_pressed = true
	await wait(0.4)
	if not ok.call("dash", hero.stats.dash >= 1):
		fails += 1
	# shard pickup: walk the shard line north
	var s0: int = int(G.data.shards)
	hero.respawn_at(world.HUB + Vector3(0, 1.5, -8), 0.0)
	cam_yaw = 0.0
	bot.move = Vector2(0, 1)
	await wait(2.2)
	bot.move = Vector2.ZERO
	if not ok.call("shards collected (%d)" % (int(G.data.shards) - s0), int(G.data.shards) > s0):
		fails += 1
	# launch pad to Emerald Steps
	var pad: Dictionary = world.pads[0]
	hero.respawn_at(pad.pos + Vector3(0, 1.0, 0), 0.0)
	await wait_until(func(): return hero.mode == "rail", 3.0)
	if not ok.call("launch pad starts flight", hero.mode == "rail"):
		fails += 1
	await wait_until(func(): return hero.mode != "rail", 10.0)
	await wait(1.0)
	if not ok.call("landed on Emerald Steps (%.0f m from landing)" % _dist_h(hero.global_position, world.L1), _dist_h(hero.global_position, world.L1) < 22.0 and hero.global_position.y > -5.0):
		fails += 1
	# take the steps core directly
	var c0: Dictionary = world.cores[0]
	hero.respawn_at(c0.pos + Vector3(0, -1.5, 3.5), 0.0)
	bot.move = Vector2(0, 1)
	cam_yaw = 0.0
	await wait_until(func(): return G.data.cores[0], 3.0)
	bot.move = Vector2.ZERO
	if not ok.call("core 1 collected", G.data.cores[0]):
		fails += 1
	# hook: stand on canyon landing near the first anchor
	var a0: Dictionary = world.anchors.filter(func(a): return a.pos.x > world.L2.x and a.pos.x < world.L2.x + 40)[0]
	hero.respawn_at(world.L2 + Vector3(16, 2, 0), -PI / 2)
	cam_yaw = -PI / 2
	cam_pitch = -0.1
	await wait(0.8)
	_update_camera(0.016)
	var cand := _find_hook()
	if not ok.call("hook target found near the canyon", not cand.is_empty()):
		fails += 1
	bot.hook_pressed = true
	await wait(0.2)
	var zipped := hero.mode == "zip"
	await wait_until(func(): return hero.mode != "zip", 4.0)
	if not ok.call("zip to anchor (zipped %s, %.1f m from anchor)" % [zipped, hero.center().distance_to(a0.pos)], zipped and hero.stats.zips >= 1):
		fails += 1
	# canyon core
	hero.respawn_at(world.cores[1].pos + Vector3(0, -1.5, 3), 0.0)
	cam_yaw = 0.0
	bot.move = Vector2(0, 1)
	await wait_until(func(): return G.data.cores[1], 3.0)
	bot.move = Vector2.ZERO
	if not ok.call("core 2 collected (hero %s, core %s, mode %s)" % [hero.global_position, world.cores[1].pos, hero.mode], G.data.cores[1]):
		fails += 1
	# foundry waves: invulnerable hero, auto fire
	hero.respawn_at(world.cores[2].pos + Vector3(0, -1.5, 8), 0.0)
	await wait_until(func(): return foundry.state == "wave", 3.0)
	if not ok.call("foundry waves start", foundry.state == "wave"):
		fails += 1
	bot.fire_held = true
	var guard_t := 0.0
	while foundry.state != "done" and guard_t < 120.0:
		hero.invuln = 1.0
		hero.hearts = hero.max_hearts
		# turn the camera toward the nearest drone
		var nd = null
		var bd := 1e9
		for d in drones:
			if not d.dead and d.spawn_t >= 1.0:
				var dd: float = d.global_position.distance_to(hero.global_position)
				if dd < bd:
					bd = dd
					nd = d
		if nd != null:
			var to: Vector3 = nd.global_position - hero.global_position
			cam_yaw = atan2(-to.x, -to.z)
			cam_pitch = clampf(atan2(to.y - 1.5, Vector2(to.x, to.z).length()), -1.0, 0.7)
		await get_tree().physics_frame
		guard_t += get_physics_process_delta_time()
	bot.fire_held = false
	if not ok.call("foundry cleared in %.0f s (%d drones down)" % [guard_t, int(G.data.drones)], foundry.state == "done"):
		fails += 1
	await wait(2.2)
	hero.respawn_at(world.cores[2].pos + Vector3(0, -1.5, 3), 0.0)
	bot.move = Vector2(0, 1)
	cam_yaw = 0.0
	await wait_until(func(): return G.data.cores[2], 3.0)
	bot.move = Vector2.ZERO
	if not ok.call("core 3 collected", G.data.cores[2]):
		fails += 1
	# rings: start on the tower, glide toward each ring
	hero.respawn_at(world.ring_start + Vector3(0, 1.0, 0), 0.0)
	await wait(0.6)
	var r0: Vector3 = world.rings[0].pos
	var to0 := r0 - hero.global_position
	cam_yaw = atan2(-to0.x, -to0.z)
	hero.facing = cam_yaw
	bot.move = Vector2(0, 1)
	bot.jump_pressed = true
	bot.jump_held = true
	await wait(0.3)
	bot.jump_pressed = true
	var rt := 0.0
	while not ring.done and rt < 60.0:
		var idx: int = mini(ring.idx, world.rings.size() - 1)
		var rp: Vector3 = world.rings[idx].pos
		var to := rp - hero.global_position
		cam_yaw = atan2(-to.x, -to.z)
		cam_idle = 0.0
		if hero.is_on_floor() and not ring.done:
			break
		await get_tree().physics_frame
		rt += get_physics_process_delta_time()
	bot.jump_held = false
	bot.move = Vector2.ZERO
	if not ok.call("ring course (%d/%d rings, %.1f s)" % [ring.idx, world.rings.size(), rt], ring.done):
		fails += 1
	if ring.done:
		hero.respawn_at(world.cores[3].pos + Vector3(0, -1.5, 3), 0.0)
		bot.move = Vector2(0, 1)
		cam_yaw = 0.0
		await wait_until(func(): return G.data.cores[3], 3.0)
		bot.move = Vector2.ZERO
	else:
		world.set_core_visible(3, true)
		hero.respawn_at(world.cores[3].pos + Vector3(0, -1.5, 3), 0.0)
		bot.move = Vector2(0, 1)
		cam_yaw = 0.0
		await wait_until(func(): return G.data.cores[3], 3.0)
		bot.move = Vector2.ZERO
	if not ok.call("core 4 collected", G.data.cores[3]):
		fails += 1
	# spire: guards spawn, then core
	hero.respawn_at(world.L5 + Vector3(0, 2, 0), 0.0)
	await wait(0.5)
	if not ok.call("spire guards spawned", spire_spawned and drones.size() >= 3):
		fails += 1
	hero.respawn_at(world.cores[4].pos + Vector3(0, -1.5, 3), 0.0)
	bot.move = Vector2(0, 1)
	cam_yaw = 0.0
	var ct := 0.0
	while not G.data.cores[4] and ct < 3.0:
		hero.invuln = 1.0
		cam_yaw = 0.0
		await get_tree().physics_frame
		ct += get_physics_process_delta_time()
	bot.move = Vector2.ZERO
	if not ok.call("core 5 collected, gate open (hero %s core %s)" % [hero.global_position, world.cores[4].pos], G.data.cores[4] and G.cores_count() == 5):
		fails += 1
	# forge
	G.data.shards = 400
	open_forge()
	var b1 := buy_upgrade("power")
	var b2 := buy_upgrade("hearts")
	var b3 := buy_paint("ember")
	close_forge()
	if not ok.call("forge purchases", b1 and b2 and b3 and hero.max_hearts == 6):
		fails += 1
	# boss
	hero.respawn_at(world.gate_pos + Vector3(0, 1, -2), 0.0)
	await wait(0.3)
	bot.interact_pressed = true
	await wait(0.3)
	if not ok.call("entered the arena", in_arena and titan != null):
		fails += 1
	if titan == null:
		log_t("RESULT: aborted, no titan")
		get_tree().quit(1)
		return
	await wait_until(func(): return titan.state != "intro", 6.0)
	bot.fire_held = true
	var bt := 0.0
	var shots0: int = hero.stats.shots
	while titan != null and not titan.dead and bt < 240.0:
		hero.invuln = 1.0
		hero.hearts = hero.max_hearts
		var tg = _pick_target()
		var tw := titan.targets()
		var aim_p: Vector3 = titan.global_position + Vector3(0, 14, 0)
		if tw.size() > 0:
			aim_p = tw[0].node.global_position
		var to := aim_p - cam.global_position
		cam_yaw = atan2(-to.x, -to.z)
		cam_pitch = clampf(atan2(to.y, Vector2(to.x, to.z).length()), -1.0, 0.7)
		# keep distance from the titan
		var away := hero.global_position - titan.global_position
		away.y = 0
		bot.move = Vector2(0, -0.6) if away.length() < 20.0 else Vector2.ZERO
		await get_tree().physics_frame
		bt += get_physics_process_delta_time()
	bot.fire_held = false
	bot.move = Vector2.ZERO
	if not ok.call("Storm Titan defeated in %.0f s (%d shots, phase reached %d)" % [bt, hero.stats.shots - shots0, titan.phase if titan != null else 4], titan == null or titan.dead):
		fails += 1
	await wait(4.5)
	if not ok.call("victory screen + storm clearing", state == "victory" and G.data.boss):
		fails += 1
	log_t("RESULT: %d failures" % fails)
	log_t("total shards %d, drones down %d, shards in world %d, prisms %d, anchors %d, pads %d, rings %d" % [int(G.data.shards), int(G.data.drones), world.shard_pos.size(), world.prism_pos.size(), world.anchors.size(), world.pads.size(), world.rings.size()])
	get_tree().quit(1 if fails > 0 else 0)

files.shaders/cloudsea.gdshader:
shader_type spatial;
render_mode cull_disabled, specular_disabled;
// Endless sea of clouds far below the islands. Fake-lit fbm with sun glints and soft shadows.

uniform sampler2D cloud_noise : filter_linear_mipmap, repeat_enable;
uniform vec3 lit_col = vec3(1.0, 0.86, 0.74);
uniform vec3 shade_col = vec3(0.55, 0.48, 0.70);
uniform vec3 deep_col = vec3(0.32, 0.28, 0.50);
uniform vec3 sun_dir = vec3(0.5, 0.45, -0.7);
uniform float speed = 1.0;
uniform float scale = 0.0035;

varying vec3 wpos;

float fbm(vec2 uv) {
	float a = texture(cloud_noise, uv).r * 0.55;
	a += texture(cloud_noise, uv * 2.13 + 0.31).g * 0.28;
	a += texture(cloud_noise, uv * 4.71 + 0.73).b * 0.17;
	return a;
}

void vertex() {
	wpos = (MODEL_MATRIX * vec4(VERTEX, 1.0)).xyz;
	vec2 uv = wpos.xz * scale + vec2(TIME * 0.0012, TIME * 0.0006) * speed;
	float h = fbm(uv);
	VERTEX.y += (h - 0.5) * 28.0;
	wpos.y += (h - 0.5) * 28.0;
}

void fragment() {
	vec2 uv = wpos.xz * scale + vec2(TIME * 0.0012, TIME * 0.0006) * speed;
	float e = 0.004;
	float h = fbm(uv);
	float hx = fbm(uv + vec2(e, 0.0));
	float hz = fbm(uv + vec2(0.0, e));
	vec3 n = normalize(vec3((h - hx) * 9.0, 1.0, (h - hz) * 9.0));
	float l = clamp(dot(n, normalize(sun_dir)) * 0.6 + 0.45, 0.0, 1.0);
	float puff = smoothstep(0.32, 0.72, h);
	vec3 col = mix(deep_col, shade_col, puff);
	col = mix(col, lit_col, l * puff);
	// rim / silver lining
	vec3 vdir = normalize((INV_VIEW_MATRIX * vec4(VIEW, 0.0)).xyz);
	float rim = pow(1.0 - clamp(dot(n, vdir), 0.0, 1.0), 3.0);
	col += lit_col * rim * 0.25 * puff;
	ALBEDO = col * 0.85;
	ROUGHNESS = 1.0;
	EMISSION = col * 0.32;
	BACKLIGHT = vec3(0.3);
}

files.shaders/energy.gdshader:
shader_type spatial;
render_mode blend_add, cull_disabled, depth_draw_never, unshaded, shadows_disabled, fog_disabled;
// Additive glowing energy surface: rings, updraft columns, portals, shields. UV.y along height.

uniform vec3 col : source_color = vec3(0.3, 0.8, 1.0);
uniform float intensity = 1.5;
uniform float scroll = 0.6;
uniform float bands = 6.0;
uniform float fade_top = 1.0;
uniform float fresnel = 1.0;
uniform float alpha_mul = 1.0;

void fragment() {
	float b = sin((UV.y * bands - TIME * scroll) * 6.2831) * 0.5 + 0.5;
	float s = sin((UV.x * 18.0 + UV.y * 3.0 + TIME * scroll * 0.7) * 6.2831) * 0.5 + 0.5;
	float f = mix(1.0, pow(1.0 - abs(dot(NORMAL, VIEW)), 1.6), fresnel);
	float fade = mix(1.0, smoothstep(1.0, 0.2, UV.y) * smoothstep(0.0, 0.08, UV.y), fade_top);
	float a = (0.25 + b * 0.5 + s * 0.15) * f * fade * alpha_mul;
	ALBEDO = col * intensity * a;
}

files.shaders/falls.gdshader:
shader_type spatial;
render_mode blend_mix, cull_disabled, depth_draw_never, specular_disabled, unshaded;
// Waterfall ribbon: scrolling streaks, fades at the bottom into the void.

uniform sampler2D streaks : filter_linear_mipmap, repeat_enable;
uniform vec3 water : source_color = vec3(0.55, 0.85, 1.0);
uniform float speed = 0.9;

void fragment() {
	vec2 uv = UV;
	float a = texture(streaks, vec2(uv.x * 2.0, uv.y * 1.2 - TIME * speed)).r;
	float b = texture(streaks, vec2(uv.x * 3.1 + 0.4, uv.y * 0.8 - TIME * speed * 1.3)).r;
	float s = clamp(a * 0.6 + b * 0.6, 0.0, 1.0);
	float edge = smoothstep(0.0, 0.15, uv.x) * smoothstep(1.0, 0.85, uv.x);
	float fade = smoothstep(1.0, 0.55, uv.y);
	ALBEDO = mix(water, vec3(1.0), s * 0.8);
	ALPHA = (0.35 + s * 0.65) * edge * fade;
}

files.shaders/grass.gdshader:
shader_type spatial;
render_mode cull_disabled, specular_disabled;
// Instanced grass clumps that sway in the wind. Vertex color.r = height along blade (0 root, 1 tip).

uniform vec3 root_col : source_color = vec3(0.08, 0.20, 0.05);
uniform vec3 tip_col : source_color = vec3(0.55, 0.72, 0.22);
uniform float wind = 1.0;
uniform vec3 hero_pos = vec3(0.0, -1000.0, 0.0);

varying float tipv;
varying vec3 tintv;

void vertex() {
	vec3 wp = (MODEL_MATRIX * vec4(VERTEX, 1.0)).xyz;
	float t = COLOR.r;
	tipv = t;
	float ph = wp.x * 0.35 + wp.z * 0.27;
	float sway = sin(TIME * 1.7 + ph) * 0.18 + sin(TIME * 3.1 + ph * 2.3) * 0.06;
	vec3 off = vec3(sway, 0.0, sway * 0.6) * wind * t * t;
	// push away from the hero
	vec3 d = wp - hero_pos;
	float dist = length(d.xz);
	if (dist < 1.6 && abs(d.y) < 2.0) {
		vec2 push = normalize(d.xz + 0.0001) * (1.6 - dist) * 0.7 * t;
		off.xz += push;
		off.y -= (1.6 - dist) * 0.25 * t;
	}
	VERTEX += (inverse(mat3(MODEL_MATRIX)) * off);
	float v = fract(sin(dot(NODE_POSITION_WORLD.xz + wp.xz * 0.01, vec2(12.9898, 78.233))) * 43758.5453);
	tintv = mix(vec3(0.9, 1.0, 0.85), vec3(1.15, 1.05, 0.8), v);
}

void fragment() {
	vec3 c = mix(root_col, tip_col, tipv) * tintv;
	ALBEDO = c;
	ROUGHNESS = 0.9;
	BACKLIGHT = vec3(0.35, 0.45, 0.15) * tipv;
	NORMAL = mix(NORMAL, (VIEW_MATRIX * vec4(0.0, 1.0, 0.0, 0.0)).xyz, 0.6);
}

files.shaders/leaves.gdshader:
shader_type spatial;
render_mode specular_schlick_ggx;
// Stylised foliage blobs: wind wobble, translucent backlight, colour variation per instance.

uniform vec3 col_a : source_color = vec3(0.16, 0.38, 0.10);
uniform vec3 col_b : source_color = vec3(0.45, 0.62, 0.15);
uniform float wobble = 1.0;

varying float hv;

void vertex() {
	vec3 wp = (MODEL_MATRIX * vec4(VERTEX, 1.0)).xyz;
	vec3 o = (MODEL_MATRIX * vec4(0.0, 0.0, 0.0, 1.0)).xyz;
	float ph = o.x * 0.21 + o.z * 0.17;
	vec3 off = vec3(sin(TIME * 1.3 + ph + wp.y * 0.4), 0.0, cos(TIME * 1.1 + ph + wp.x * 0.3)) * 0.08 * wobble;
	VERTEX += inverse(mat3(MODEL_MATRIX)) * off;
	hv = fract(sin(dot(o.xz, vec2(12.9898, 78.233))) * 43758.5453);
}

void fragment() {
	vec3 wn = (INV_VIEW_MATRIX * vec4(NORMAL, 0.0)).xyz;
	float up = wn.y * 0.5 + 0.5;
	vec3 c = mix(col_a, col_b, clamp(up * 0.8 + hv * 0.4 - 0.15, 0.0, 1.0));
	ALBEDO = c;
	ROUGHNESS = 0.8;
	BACKLIGHT = c * 0.8;
}

files.shaders/puff.gdshader:
shader_type spatial;
render_mode specular_disabled, cull_back;
// Soft cumulus puffs (instanced). Wobbly vertex noise, wrap lighting, silver rim.

uniform vec3 lit_col = vec3(1.0, 0.93, 0.86);
uniform vec3 shade_col = vec3(0.62, 0.58, 0.78);
uniform float storm = 0.0;

varying vec3 wn;

void vertex() {
	vec3 wp = (MODEL_MATRIX * vec4(VERTEX, 1.0)).xyz;
	float w = sin(wp.x * 0.13 + TIME * 0.4) * cos(wp.z * 0.11 + TIME * 0.33) * sin(wp.y * 0.2 + TIME * 0.27);
	VERTEX += NORMAL * w * 0.12;
	wn = normalize((MODEL_MATRIX * vec4(NORMAL, 0.0)).xyz);
}

void fragment() {
	vec3 vd = normalize((INV_VIEW_MATRIX * vec4(VIEW, 0.0)).xyz);
	float rim = pow(1.0 - clamp(dot(normalize(wn), vd), 0.0, 1.0), 2.5);
	float up = wn.y * 0.5 + 0.5;
	vec3 lc = mix(lit_col, vec3(0.42, 0.38, 0.55), storm);
	vec3 sc = mix(shade_col, vec3(0.18, 0.15, 0.28), storm);
	vec3 col = mix(sc, lc, smoothstep(0.1, 0.9, up));
	ALBEDO = col * 0.75;
	EMISSION = col * 0.28 + lc * rim * 0.35;
	ROUGHNESS = 1.0;
	BACKLIGHT = vec3(0.4);
}

void light() {
	float wrap = clamp(dot(NORMAL, LIGHT) * 0.5 + 0.5, 0.0, 1.0);
	DIFFUSE_LIGHT += wrap * ATTENUATION * LIGHT_COLOR * ALBEDO / 3.14159;
}

files.shaders/shard.gdshader:
shader_type spatial;
render_mode specular_schlick_ggx;
// Spinning, bobbing collectible sky shards (instanced). Bright gem with glow.

uniform vec3 col : source_color = vec3(0.35, 0.85, 1.0);
uniform float glow = 1.6;

void vertex() {
	float ph = float(INSTANCE_ID) * 1.618;
	float a = TIME * 2.2 + ph;
	mat3 r = mat3(vec3(cos(a), 0.0, -sin(a)), vec3(0.0, 1.0, 0.0), vec3(sin(a), 0.0, cos(a)));
	VERTEX = r * VERTEX;
	NORMAL = r * NORMAL;
	VERTEX.y += sin(TIME * 2.0 + ph) * 0.12;
}

void fragment() {
	float f = pow(1.0 - abs(dot(NORMAL, VIEW)), 2.0);
	ALBEDO = col * 0.6;
	METALLIC = 0.3;
	ROUGHNESS = 0.15;
	EMISSION = col * (glow * 0.6 + f * glow);
}

files.shaders/sky.gdshader:
shader_type sky;
// Golden-hour sky with sun, soft high clouds and a stormy tint toward the storm direction.

uniform sampler2D cloud_noise : filter_linear_mipmap, repeat_enable;
uniform vec3 zenith = vec3(0.10, 0.22, 0.55);
uniform vec3 horizon = vec3(0.98, 0.70, 0.48);
uniform vec3 ground_col = vec3(0.70, 0.62, 0.72);
uniform vec3 storm_dir = vec3(0.0, 0.0, 1.0);
uniform float storm = 1.0;
uniform vec3 storm_col = vec3(0.22, 0.14, 0.35);
uniform float flash = 0.0;
uniform float clear_sky = 0.0;

void sky() {
	vec3 d = EYEDIR;
	float h = d.y;
	vec3 zen = mix(zenith, vec3(0.12, 0.36, 0.78), clear_sky);
	vec3 hor = mix(horizon, vec3(0.98, 0.82, 0.62), clear_sky);
	vec3 col = mix(hor, zen, pow(clamp(h, 0.0, 1.0), 0.55));
	col = mix(col, ground_col, smoothstep(0.0, -0.25, h));
	// sun
	vec3 sd = LIGHT0_DIRECTION;
	float sdot = max(dot(d, sd), 0.0);
	vec3 sunc = LIGHT0_COLOR;
	col += sunc * pow(sdot, 8.0) * 0.35;
	col += sunc * pow(sdot, 64.0) * 0.6;
	col += sunc * smoothstep(0.9993, 0.9997, sdot) * 6.0;
	// high clouds
	if (h > -0.02) {
		vec2 uv = d.xz / (h + 0.12) * 0.22 + vec2(TIME * 0.0025, TIME * 0.001);
		float c = texture(cloud_noise, uv).r * 0.6 + texture(cloud_noise, uv * 2.7).g * 0.4;
		c = smoothstep(0.52, 0.85, c) * smoothstep(-0.02, 0.18, h);
		vec3 cc = mix(vec3(1.0, 0.85, 0.75), vec3(1.0), clear_sky) * (0.75 + 0.6 * pow(sdot, 4.0));
		col = mix(col, cc, c * 0.65);
	}
	// storm glow on horizon toward storm
	float sdir = max(dot(normalize(vec3(d.x, 0.0, d.z)), storm_dir), 0.0);
	float band = smoothstep(0.35, -0.02, h) * smoothstep(-0.2, 0.0, h);
	col = mix(col, storm_col, pow(sdir, 6.0) * band * storm * 0.85);
	col += vec3(0.6, 0.6, 1.0) * flash * pow(sdir, 4.0) * band;
	COLOR = col;
}

files.shaders/terrain.gdshader:
shader_type spatial;
// Floating-island terrain: triplanar layered rock on cliffs, grass (or dirt) on top.
// Vertex color: r = top-material mask, g = path/dirt mask, b = darken (underside / AO)

uniform sampler2D rock_albedo : source_color, filter_linear_mipmap_anisotropic, repeat_enable;
uniform sampler2D rock_normal : hint_normal, filter_linear_mipmap_anisotropic, repeat_enable;
uniform sampler2D top_albedo : source_color, filter_linear_mipmap_anisotropic, repeat_enable;
uniform sampler2D top_normal : hint_normal, filter_linear_mipmap_anisotropic, repeat_enable;
uniform sampler2D dirt_albedo : source_color, filter_linear_mipmap_anisotropic, repeat_enable;
uniform vec3 rock_tint = vec3(1.0);
uniform vec3 top_tint = vec3(1.0);
uniform float rock_scale = 0.07;
uniform float top_scale = 0.18;
uniform float bump = 1.0;
uniform float glow_amount = 0.0;
uniform vec3 glow_color = vec3(0.3, 0.8, 1.0);

varying vec3 wpos;
varying vec3 wnrm;

void vertex() {
	wpos = (MODEL_MATRIX * vec4(VERTEX, 1.0)).xyz;
	wnrm = normalize((MODEL_MATRIX * vec4(NORMAL, 0.0)).xyz);
}

void fragment() {
	vec3 n = normalize(wnrm);
	vec3 w = pow(abs(n), vec3(4.0));
	w /= (w.x + w.y + w.z);
	vec3 p = wpos * rock_scale;
	vec2 uvx = vec2(p.z, -p.y);
	vec2 uvy = p.xz;
	vec2 uvz = vec2(p.x, -p.y);
	vec3 rock = (texture(rock_albedo, uvx).rgb * w.x + texture(rock_albedo, uvy).rgb * w.y + texture(rock_albedo, uvz).rgb * w.z) * rock_tint;
	// whiteout triplanar normal blend (world space)
	vec3 tx = texture(rock_normal, uvx).rgb * 2.0 - 1.0;
	vec3 ty = texture(rock_normal, uvy).rgb * 2.0 - 1.0;
	vec3 tz = texture(rock_normal, uvz).rgb * 2.0 - 1.0;
	tx.xy *= bump; ty.xy *= bump; tz.xy *= bump;
	vec3 nx = vec3(tx.xy + n.zy, abs(tx.z) * n.x);
	vec3 ny = vec3(ty.xy + n.xz, abs(ty.z) * n.y);
	vec3 nzz = vec3(tz.xy + n.xy, abs(tz.z) * n.z);
	vec3 rockN = normalize(nx.zyx * w.x + ny.xzy * w.y + nzz.xyz * w.z);
	// top material
	vec2 tuv = wpos.xz * top_scale;
	vec3 top = texture(top_albedo, tuv).rgb;
	top = mix(top, texture(top_albedo, tuv * 0.23 + 0.37).rgb, 0.45) * top_tint;
	vec3 dirt = texture(dirt_albedo, tuv * 0.8).rgb;
	vec3 tn = texture(top_normal, tuv).rgb * 2.0 - 1.0;
	vec3 topN = normalize(vec3(tn.x * 0.6, 1.0, -tn.y * 0.6));
	float up = smoothstep(0.55, 0.82, n.y) * COLOR.r;
	float nz = texture(top_albedo, wpos.xz * 0.031).g;
	up = clamp(up + (nz - 0.4) * 0.6 * up * (1.0 - up) * 4.0, 0.0, 1.0);
	vec3 topc = mix(top, dirt, COLOR.g);
	vec3 col = mix(rock, topc, up);
	col *= mix(1.0, 0.45, COLOR.b);
	ALBEDO = col;
	vec3 wn = normalize(mix(rockN, normalize(n + (topN - vec3(0.0, 1.0, 0.0))), up));
	NORMAL = normalize((VIEW_MATRIX * vec4(wn, 0.0)).xyz);
	ROUGHNESS = mix(0.86, 0.95, up);
	SPECULAR = 0.25;
	EMISSION = glow_color * glow_amount * (1.0 - up) * smoothstep(0.55, 0.95, rock.b) ;
}

files.shaders/vortex.gdshader:
shader_type spatial;
render_mode blend_mix, cull_disabled, depth_draw_never, specular_disabled, unshaded, fog_disabled;
// The storm wall: swirling dark clouds on a huge open cylinder, with lightning flashes.

uniform sampler2D cloud_noise : filter_linear_mipmap, repeat_enable;
uniform vec3 dark : source_color = vec3(0.12, 0.08, 0.22);
uniform vec3 lite : source_color = vec3(0.45, 0.32, 0.65);
uniform float flash = 0.0;
uniform float strength = 1.0;

void fragment() {
	vec2 uv = vec2(UV.x * 3.0 + TIME * 0.02 + UV.y * 0.6, UV.y * 1.4 - TIME * 0.01);
	float n = texture(cloud_noise, uv).r * 0.6 + texture(cloud_noise, uv * 2.3 + vec2(TIME * 0.015, 0.0)).g * 0.4;
	float c = smoothstep(0.3, 0.8, n);
	vec3 colr = mix(dark, lite, c);
	colr += vec3(0.7, 0.75, 1.0) * flash * c;
	float edge = smoothstep(0.0, 0.18, UV.y) * smoothstep(1.0, 0.75, UV.y);
	ALBEDO = colr;
	ALPHA = clamp((0.55 + c * 0.45) * edge * strength, 0.0, 1.0);
}
